// @ts-strict-ignore
import { DateHelper, GroupAdmissionHelper, isNonEmptyArray, multipleClassNames } from "@/core/helpers";
import {
  GroupAdmissionState,
  Guest,
  SelectablePass,
  VisitDate,
} from "@/core/types/state/group-admission/group-admission-types";
import { EntryVariant, VisitorCategory } from "@/core/types/services/purchase-flow-service-types";
import { corei18n } from "@/core/labels/i18n";
import styles from "./step-summary.module.less";
import { useTranslation } from "react-i18next";
import { OpeningHoursItem } from "@parksandresorts/webapiproxy-types";

const getSelectedDatesString = (selectedDates: Map<string, VisitDate>): string => {
  if (selectedDates.size === 0) {
    return null;
  }

  const selectedDatesString = [...selectedDates.values()]
    .map((date, index) => {
      if (DateHelper.isToday(date.date)) {
        return `${corei18n.t("today")} ${DateHelper.toStringMMDDWeekday(date.date)}`;
      }
      const dateString = DateHelper.toStringMMDDWeekday(date.date);
      return index !== 0 ? dateString : dateString.charAt(0).toUpperCase() + dateString.slice(1);
    })
    .join(" - ");

  return selectedDatesString;
};

const StepSummaryParagraph = ({ text }: { text: string }) => {
  return <p className={multipleClassNames(styles.summaryParagraph, "p_small")}>{text}</p>;
};

export const FixedDateStepSummary = ({
  selectedDates,
  showOpeningHoursInFixedDateSummary = false,
  selectedDateOpeningHours,
}: {
  selectedDates: Map<string, VisitDate>;
  showOpeningHoursInFixedDateSummary: boolean;
  selectedDateOpeningHours?: Pick<OpeningHoursItem, "opens" | "closing">;
}) => {
  const { t } = useTranslation();

  const showOpeningHours =
    showOpeningHoursInFixedDateSummary && selectedDateOpeningHours?.opens && selectedDateOpeningHours?.closing;
  const openingHoursText = showOpeningHours
    ? t("stepWrapperFixedDateOpeningHours", [
        DateHelper.toStringTimeHHMM(selectedDateOpeningHours?.opens),
        DateHelper.toStringTimeHHMM(selectedDateOpeningHours?.closing),
      ])
    : "";

  return (
    <>
      <StepSummaryParagraph text={getSelectedDatesString(selectedDates)} />
      {showOpeningHours && <StepSummaryParagraph text={openingHoursText} />}
    </>
  );
};

export const GroupSizeStepSummary = ({
  quantity,
  visitorCategories,
}: {
  quantity: GroupAdmissionState["quantity"];
  visitorCategories: Map<VisitorCategory["id"], VisitorCategory>;
}) => {
  const quantityStringArray = [];
  for (const [key, value] of quantity) {
    if (value > 0) {
      const visitorCategory = visitorCategories.get(key);
      quantityStringArray.push(corei18n.t("groupSizeStepSummary", [value, visitorCategory.name]));
    }
  }
  return <StepSummaryParagraph text={quantityStringArray.join(", ").toLowerCase()} />;
};

export const SelectDateStepSummary = ({
  selectedDates,
  selectedVariant,
  entryVariantType,
  hideVariant,
}: {
  selectedDates: Map<string, VisitDate>;
  selectedVariant: EntryVariant;
  entryVariantType: string;
  hideVariant?: boolean;
}) => {
  if (selectedDates.size === 0) {
    return null;
  }
  const dateString = getSelectedDatesString(selectedDates);

  switch (entryVariantType) {
    case "PartOfDay":
      return (
        <StepSummaryParagraph
          text={hideVariant ? dateString : `${dateString} - ${selectedVariant && selectedVariant.name}`}
        />
      );
    case "NumberOfDays":
    default:
      return <StepSummaryParagraph text={dateString} />;
  }
};

export const SelectEntryTimeStepSummary = ({ selectedEntryTime }: { selectedEntryTime: SelectablePass }) => {
  if (!selectedEntryTime) {
    return null;
  }
  return (
    <StepSummaryParagraph
      text={`${selectedEntryTime.attractionName} ${DateHelper.toStringTimeHHMM(selectedEntryTime.timeSlotFrom)}`}
    />
  );
};

export const SelectTicketStepSummary = ({ guests }: { guests: Array<Guest> }) => {
  return <StepSummaryParagraph text={`${corei18n.t("stepWrapperSelectedTickets", { count: guests.length })}`} />;
};

export const SelectMandatoryJetpassStepSummary = ({ guests }: { guests: Array<Guest> }) => {
  if (!isNonEmptyArray(guests)) {
    return null;
  }

  const firstGuest = [...guests][0];
  const selectedMandatoryJetpass = firstGuest.admissionProduct.selectedMandatoryJetpass;
  if (!selectedMandatoryJetpass) {
    return null;
  }

  return (
    <StepSummaryParagraph
      text={`${selectedMandatoryJetpass.attractionName} ${DateHelper.toStringTimeHHMM(
        selectedMandatoryJetpass.timeSlotFrom,
      )}`}
    />
  );
};

export const SelectJetpassStepSummary = ({
  guests,
  jetpassMaxLimit,
  guestsHaveNoJetpasses,
}: {
  guests: Array<Guest>;
  jetpassMaxLimit?: number;
  guestsHaveNoJetpasses?: boolean;
}) => {
  if (guestsHaveNoJetpasses) return null;
  const jetPassSummary = guests.reduce(
    (summary, guest) => {
      const totalSelected = guest.admissionProduct.selectedJetpasses?.length ?? 0;
      const totalAvailable = guest.admissionProduct.numberOfJetpassIncluded;

      return {
        totalSelected: summary.totalSelected + totalSelected,
        totalAvailable: summary.totalAvailable + totalAvailable,
      };
    },
    { totalSelected: 0, totalAvailable: 0 },
  );

  if (GroupAdmissionHelper.hasGuestsExeededJetpassLimit(guests, jetpassMaxLimit)) {
    return (
      <StepSummaryParagraph
        text={`${jetPassSummary.totalAvailable} ${corei18n.t("stepWrapperJetPassLimitExceeded")}`}
      />
    );
  }

  return (
    <StepSummaryParagraph
      text={`${jetPassSummary.totalSelected} ${corei18n.t("of")} ${jetPassSummary.totalAvailable} ${corei18n.t(
        "stepWrapperBookedJetPasses",
      )}`}
    />
  );
};

export const UpsellStepSummary = ({ selectedDates }: { selectedDates: Map<string, VisitDate> }) => {
  let numberOfProducts = 0;

  for (const [, visitDate] of selectedDates) {
    numberOfProducts += visitDate?.selectedUpsellProducts.size ?? 0;
  }

  // upsellProducts.forEach((product, key) => {
  //     numberOfProducts += product.quantity;
  // })

  return <StepSummaryParagraph text={corei18n.t("stepWrapperBookedExperiences", { count: numberOfProducts })} />;
};
