import { CartRequestCartItem, CartResponseV2CartItem, DeliveryType } from "@parksandresorts/webapiproxy-types";
import {
  Guest,
  PurchaseFlowDate,
  SelectedUpsellProduct,
  VisitDate,
} from "@/core/types/state/group-admission/group-admission-types";
import { DateHelper, getPrimaryDeliveryType, isTruthy, throwError } from "@/core/helpers";
import { useTranslation } from "react-i18next";
import { range } from "lodash-es";
import { ShopServiceCartContextModifiers, useShopServiceCartContext } from "@/core/contexts";
import { useEffect, useMemo, useState } from "react";
import { cartItemHasChanged, diffCartItems } from "@/core/helpers/klarna-functions";
import { NormalizedProduct, useProducts } from "@/core/hooks/product-hooks";

function deliveryTypeForProduct(
  productsById: ReadonlyMap<number, NormalizedProduct | undefined>,
  productId: number,
): CartRequestCartItem["deliveryType"] {
  const product = productsById.get(productId);
  return getPrimaryDeliveryType(product, DeliveryType.DIGITAL);
}

function standardUpsellProductToCartItem(
  productsById: ReadonlyMap<number, NormalizedProduct | undefined>,
  upsellProduct: SelectedUpsellProduct,
): CartRequestCartItem {
  return {
    productId: upsellProduct.productId,
    quantity: upsellProduct.quantity,
    deliveryType: deliveryTypeForProduct(productsById, upsellProduct.productId),
  };
}

/**
 * Timeslot-based products can only have quantity 1, because each one needs to have its own barcode.
 * This function will create a separate list of cart items with quantity 1 for each quantity of the product.
 */
function timeSlotUpsellProductToCartItem(
  productsById: ReadonlyMap<number, NormalizedProduct | undefined>,
  upsellProduct: SelectedUpsellProduct & Required<Pick<SelectedUpsellProduct, "timeSlot">>,
  calendarData: PurchaseFlowDate,
  guestFallbackName: string,
): Array<CartRequestCartItem> {
  const baseProduct: CartRequestCartItem = {
    ...standardUpsellProductToCartItem(productsById, upsellProduct),
    quantity: 1,
  };

  return range(upsellProduct.quantity).map((idx) => ({
    ...baseProduct,
    visitorName: `${guestFallbackName} ${idx + 1}`,
    slot: {
      slotId:
        calendarData.upsellProductsForDate.find((p) => p.productId === upsellProduct.productId)?.dateSlot.dateSlotId ??
        throwError(
          `Somehow added a timeslot-based upsell product without a valid date slot. Product: ${upsellProduct.productId} Date: ${calendarData.date}`,
        ),
      date: DateHelper.toStringYYYYMMDD(calendarData.date),
    },
    subItems: [
      {
        productId: upsellProduct.timeSlot.productId,
        quantity: 1,
        deliveryType: deliveryTypeForProduct(productsById, upsellProduct.timeSlot.productId),
        slot: {
          slotId: upsellProduct.timeSlot.timeSlotId,
          date: DateHelper.toStringYYYYMMDD(calendarData.date),
        },
      },
    ],
  }));
}

function toShopServiceProduct(
  productsById: ReadonlyMap<number, NormalizedProduct | undefined>,
  guests: Array<Guest>,
  visitDatesArray: Array<[VisitDate, PurchaseFlowDate]>,
  guestFallbackName: string,
): Array<CartRequestCartItem> {
  if (productsById.size === 0) return [];

  const entranceProducts = guests.map((guest, idx): CartRequestCartItem => {
    const jetPasses = [
      guest.admissionProduct.selectedMandatoryJetpass,
      ...guest.admissionProduct.selectedJetpasses,
      ...visitDatesArray.map(([visitDate]) => visitDate.selectedEntryTime),
    ].filter(isTruthy);
    const timeSlots = jetPasses.map(
      (jetPass): CartRequestCartItem => ({
        productId: jetPass.productId,
        quantity: 1,
        deliveryType: deliveryTypeForProduct(productsById, jetPass.productId),
        slot: { slotId: jetPass.timeSlotId, date: DateHelper.toStringYYYYMMDD(jetPass.timeSlotFrom) },
      }),
    );

    return {
      productId: guest.admissionProduct.id,
      quantity: 1,
      deliveryType: deliveryTypeForProduct(productsById, guest.admissionProduct.id),
      slot: guest.admissionProduct.dateSlotId
        ? {
            slotId: guest.admissionProduct.dateSlotId,
            date: DateHelper.toStringYYYYMMDD(guest.admissionProduct.dateSlot.date),
          }
        : undefined,
      subItems: timeSlots,
      visitorName: guest.name ?? `${guestFallbackName} ${idx + 1}`,
    };
  });

  const upsellProducts = visitDatesArray.flatMap(([visitDate, calendarData]) =>
    [...visitDate.selectedUpsellProducts.values()].flatMap((upsellProduct) => {
      if (upsellProduct.timeSlot !== undefined) {
        return timeSlotUpsellProductToCartItem(
          productsById,
          // This cast is necessary since TypeScript is not able to infer that `upsellProduct.timeSlot` is defined here. Not sure why.
          upsellProduct as typeof upsellProduct & Required<Pick<typeof upsellProduct, "timeSlot">>,
          calendarData,
          guestFallbackName,
        );
      }
      return standardUpsellProductToCartItem(productsById, upsellProduct);
    }),
  );

  return [...entranceProducts, ...upsellProducts];
}

const executeOneCartUpdate = async (
  previousCartItems: Array<CartResponseV2CartItem>,
  cartItems: Array<CartRequestCartItem>,
  modifiers: Pick<ShopServiceCartContextModifiers, "addCartItem" | "addMultipleCartItems" | "removeCartItem">,
): Promise<{ didAdd: boolean; items: Array<CartResponseV2CartItem> }> => {
  const diff = diffCartItems(previousCartItems, cartItems);
  if (diff === "noop") {
    return { didAdd: false, items: [] };
  }
  if (diff === "new") {
    return { didAdd: true, items: await modifiers.addMultipleCartItems(cartItems) };
  }
  const {
    added: [firstAddedItem],
    removed: [firstRemovedItem],
    updated: [firstUpdatedItem],
  } = diff;

  if (firstRemovedItem) {
    return { didAdd: false, items: [await modifiers.removeCartItem(firstRemovedItem.cartItemGuid)] };
  }
  if (firstUpdatedItem) {
    const [existingItem, newItem] = firstUpdatedItem;
    const changeType = cartItemHasChanged(existingItem, newItem);
    if (changeType !== null) {
      return { didAdd: false, items: [await modifiers.removeCartItem(existingItem.cartItemGuid)] };
    } else {
      console.error(
        "Item marked as needing update, but no change type found. This should never happen!",
        existingItem,
        newItem,
      );
    }
  }
  if (firstAddedItem) {
    return { didAdd: true, items: await modifiers.addCartItem(firstAddedItem) };
  }
  return { didAdd: false, items: [] };
};

export function useCartHandlerForPurchaseflow(
  guests: Array<Guest>,
  visitDatesArray: Array<[VisitDate, PurchaseFlowDate]>,
  isActive: boolean,
) {
  const { t } = useTranslation();
  const {
    addCartItem,
    addMultipleCartItems,
    removeCartItem,
    data: cart,
    isLoading: isCartLoading,
  } = useShopServiceCartContext();

  const [error, setError] = useState<unknown | null>(null);

  const productIds = useMemo(
    () => [
      ...guests.flatMap((guest) => {
        const admissionProductId = guest.admissionProduct.id;
        const jetPassProductIds = [
          guest.admissionProduct.selectedMandatoryJetpass,
          ...guest.admissionProduct.selectedJetpasses,
        ]
          .filter(isTruthy)
          .map((jp) => jp.productId);
        return [admissionProductId, ...jetPassProductIds];
      }),
      ...visitDatesArray.flatMap(([visitDate]) =>
        [...visitDate.selectedUpsellProducts.values()].flatMap((upsellProduct) => {
          const upsellProductIds = [upsellProduct.productId];
          if (upsellProduct.timeSlot) {
            upsellProductIds.push(upsellProduct.timeSlot.productId);
          }
          return upsellProductIds;
        }),
      ),
    ],
    [guests, visitDatesArray],
  );
  const { productsById } = useProducts(productIds);

  const [knownCartItems, setKnownCartItems] = useState<Array<CartResponseV2CartItem>>([]);
  const cartItems = toShopServiceProduct(productsById, guests, visitDatesArray, t("guest"));

  const diff = diffCartItems(knownCartItems, cartItems);
  // We need to use a constant value for the useEffect dependency array, so we use the lengths as an approximation, but
  // bit-shifted so that the values are "unique". This makes it so if we move from having 1 added item to 1 removed
  // item, we consider those as different.
  const diffAsDep =
    typeof diff === "string" ? diff : (diff.added.length << 16) + (diff.removed.length << 8) + diff.updated.length;

  // When (re-)entering the flow, the cart may already contain items belonging to this flow (the cart id is kept in
  // local storage). They are not in `knownCartItems` (which starts empty), so we adopt every cart item belonging to
  // this flow's products exactly once, before the reconcile loop runs. The loop then brings the cart to the desired
  // set, removing adopted items that are no longer wanted and adding the missing ones. Without this the loop would
  // re-add existing products (risking an endless loop) and leave unrecognized items behind as stray "existing items".
  const flowProductIds = useMemo(() => new Set(productIds), [productIds]);
  const [hasSeededFromCart, setHasSeededFromCart] = useState(false);
  useEffect(() => {
    if (hasSeededFromCart || !isActive || isCartLoading) {
      return;
    }
    if (cart) {
      const trackedGuids = new Set(knownCartItems.map((item) => item.cartItemGuid));
      const flowCartItems = cart.cartItems.filter(
        (cartItem) => !trackedGuids.has(cartItem.cartItemGuid) && flowProductIds.has(cartItem.productId),
      );
      if (flowCartItems.length > 0) {
        setKnownCartItems((prevKnownCartItems) => [...prevKnownCartItems, ...flowCartItems]);
      }
    }
    setHasSeededFromCart(true);
    // We intentionally omit `knownCartItems`: seeding should only run once, when the step is first activated.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasSeededFromCart, isActive, isCartLoading, cart, flowProductIds]);

  // This state is used to prevent parallell updates, which might cause us to try to delete the same item twice, which would cause an error.
  const [isUpdating, setIsUpdating] = useState(false);
  useEffect(() => {
    if (!isActive || isUpdating || diffAsDep === "noop" || error || !hasSeededFromCart) {
      return;
    }

    Promise.resolve().then(async () => {
      setIsUpdating(true);
      try {
        const { didAdd, items } = await executeOneCartUpdate(knownCartItems, cartItems, {
          addCartItem,
          addMultipleCartItems,
          removeCartItem,
        });

        if (didAdd) {
          setKnownCartItems((prevKnownCartItems) => [...prevKnownCartItems, ...items]);
        } else {
          setKnownCartItems((prevKnownCartItems) =>
            prevKnownCartItems.filter((item) => !items.some((i) => i.cartItemGuid === item.cartItemGuid)),
          );
        }
      } catch (e) {
        setError(e);
      } finally {
        setIsUpdating(false);
      }
    });
    // This complains about `cart` and `cartItems`, but we use `diffAsDep` as a stand-in for them.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isUpdating, diffAsDep, isActive, addCartItem, addMultipleCartItems, removeCartItem, hasSeededFromCart]);

  // Reset the error state when the step is activated, so that we can retry the update.
  useEffect(() => {
    setError(null);
  }, [isActive]);

  // The cart is ready for payment if:
  // 1. This is the active step
  // 2. We are not currently updating the cart. In that case, we want to wait for the update to finish.
  // 3. The diff is "noop", meaning that the cart contains all the items from this Group Admission purchase flow.
  const cartReadyForPayment = isActive && !isUpdating && diff == "noop";

  return {
    cartItems: knownCartItems,
    cartReadyForPayment,
    error,
  };
}
