import { useEffect, useMemo, useState } from "react";
import {
  Dispatchable,
  Guest,
  PurchaseFlowDate,
  SelectablePass,
  SelectedUpsellProduct,
} from "@/core/types/state/group-admission/group-admission-types";
import styles from "./upsell-list.module.less";
import UpsellItem from "../upsell-item/upsell-item";
import { isNonEmptyArray } from "@/core/helpers";
import { ITimeSlot } from "@/core/types/time-slots";
import {
  getTimeSlotsForAllUpsellProductTypes,
  getTimeSlotsForEachUpsellProductType,
  filterTimeSlotsOnSelectedEntryTimeSlot,
  filterUpsellTimeSlotsByRideTimeLimits,
} from "../upsell-functions";
import { EntryVariant } from "@/core/types/services/purchase-flow-service-types";
import { useTranslation } from "react-i18next";
import { ProductMenuResponse } from "@/core/types/services/time-slot-service";
import { GlkBackedProduct, useProducts } from "@/core/hooks/product-hooks";
import { WebshopProductType } from "@parksandresorts/webapiproxy-types";

type UpsellListProps = {
  upsellProductIds: Array<number>;
  selectedDate: PurchaseFlowDate;
  selectedEntryTimeSlot: SelectablePass;
  totalGroupSize: number;
  selectedUpsellProducts: Map<number, SelectedUpsellProduct> | null;
  selectedVariant: EntryVariant;
  guests: Array<Guest>;
  setAnyUpsellProductsAvailable: (value: boolean) => void;
} & Dispatchable;

type GuestWithRideTimes = Guest & {
  admissionProduct: {
    timeLimits: {
      firstRideTime: string;
      lastRideTime: string;
    };
  };
};

const filterTimeSlotsByRideTimeOrEntry = (
  timeSlotsForProduct: ITimeSlot[],
  selectedEntryTimeSlot: SelectablePass,
  guests: Guest[],
  product: GlkBackedProduct,
) => {
  const firstGuestWithRideTimes = guests.find((guest): guest is GuestWithRideTimes => {
    return !!guest.admissionProduct?.timeLimits?.firstRideTime && !!guest.admissionProduct?.timeLimits?.lastRideTime;
  });

  const findTimePassRequired = guests.some((guest) => {
    return guest.admissionProduct?.timePassRequired || false;
  });

  const filteredTimeSlotsQuantities: Array<ITimeSlot> = timeSlotsForProduct.filter((slot) => slot.quantity > 0);

  const noRideTimeLimitsConfigured = firstGuestWithRideTimes ? false : true;
  const noTimePassRequired = findTimePassRequired ? false : true;

  if (product.contentfulProduct?.purchasableOutsideEntryTime || (noRideTimeLimitsConfigured && noTimePassRequired)) {
    return { disabled: false, timeSlots: filteredTimeSlotsQuantities };
  }

  if (firstGuestWithRideTimes && !findTimePassRequired) {
    const firstRideTimeLimit = firstGuestWithRideTimes.admissionProduct.timeLimits.firstRideTime;
    const lastRideTimeLimit = firstGuestWithRideTimes.admissionProduct.timeLimits.lastRideTime;

    const filteredTimeSlotsOnRideTime = filterUpsellTimeSlotsByRideTimeLimits(
      filteredTimeSlotsQuantities,
      firstRideTimeLimit,
      lastRideTimeLimit,
    );
    return {
      disabled: isNonEmptyArray(filteredTimeSlotsOnRideTime) ? false : true,
      timeSlots: filteredTimeSlotsOnRideTime,
    };
  }

  if (selectedEntryTimeSlot) {
    const filteredTimeSlotsOnSelectedEntryTimeSlot = filterTimeSlotsOnSelectedEntryTimeSlot(
      filteredTimeSlotsQuantities,
      selectedEntryTimeSlot,
    );
    return {
      disabled: isNonEmptyArray(filteredTimeSlotsOnSelectedEntryTimeSlot) ? false : true,
      timeSlots: filteredTimeSlotsQuantities,
    };
  }

  return { disabled: true, timeSlots: timeSlotsForProduct };
};

const sortUpsellProducts = (
  products: Array<GlkBackedProduct>,
  timeSlotsForProductsForDate: Map<number, ProductMenuResponse> | null,
  selectedEntryTimeSlot: SelectablePass,
  guests: Guest[],
) => {
  const sortedUpsellProducts = products
    .map((product) => {
      if (product.glkProduct?.productType === WebshopProductType.STANDARD) {
        return {
          ...product,
          disabled: false,
          timeSlots: null,
        };
      }
      const timeSlotsForProduct = getTimeSlotsForEachUpsellProductType(product, timeSlotsForProductsForDate);

      if (isNonEmptyArray(timeSlotsForProduct)) {
        const filteredTimeSlotsByRideTimeOrEntry = filterTimeSlotsByRideTimeOrEntry(
          timeSlotsForProduct,
          selectedEntryTimeSlot,
          guests,
          product,
        );
        return {
          ...product,
          disabled: filteredTimeSlotsByRideTimeOrEntry.disabled,
          timeSlots: filteredTimeSlotsByRideTimeOrEntry.timeSlots,
        };
      }

      return {
        ...product,
        disabled: true,
        timeSlots: [],
      };
    })
    .sort((a, b) => {
      if (!a.disabled && b.disabled) {
        return -1;
      }
      if (a.disabled && !b.disabled) {
        return 1;
      }
      return 0;
    });

  return sortedUpsellProducts;
};

const UpsellList = ({
  upsellProductIds,
  selectedDate,
  totalGroupSize,
  selectedUpsellProducts,
  selectedEntryTimeSlot,
  selectedVariant,
  guests,
  setAnyUpsellProductsAvailable,
  dispatch,
}: UpsellListProps) => {
  const [timeSlotsForProductsForDate, setTimeSlotsForProductsForDate] = useState<Map<
    number,
    ProductMenuResponse
  > | null>(null);
  const [isLoadingTimeSlots, setIsLoadingTimeSlots] = useState(false);
  const { t } = useTranslation();

  const { productList: products } = useProducts(upsellProductIds);

  const sortedUpsellProducts = useMemo(
    () => sortUpsellProducts(products, timeSlotsForProductsForDate, selectedEntryTimeSlot, guests),
    [products, timeSlotsForProductsForDate, selectedEntryTimeSlot, guests],
  );

  useEffect(() => {
    if (!selectedDate) {
      return;
    }

    const upsellProductsWithTimeSlotsToFetch = products.filter(
      (product) =>
        product.glkProduct.productType !== WebshopProductType.STANDARD &&
        // for products that are timeslot-based, we only care about those that are relevant for the selected date
        selectedDate.upsellProductsForDate.some((p) => p.productId === product.productId),
    );

    if (isNonEmptyArray(upsellProductsWithTimeSlotsToFetch)) {
      setIsLoadingTimeSlots(true);
      getTimeSlotsForAllUpsellProductTypes(upsellProductsWithTimeSlotsToFetch, selectedDate.date)
        .then((responses) => {
          const productTimeSlotsResponseMap = new Map(
            upsellProductsWithTimeSlotsToFetch.map(({ productId }, i) => [productId, responses[i] ?? []]),
          );
          setTimeSlotsForProductsForDate(productTimeSlotsResponseMap);
        })
        .catch((err) => {
          console.error(err);
        })
        .finally(() => {
          setIsLoadingTimeSlots(false);
        });
    }
  }, [selectedDate, selectedVariant, selectedEntryTimeSlot, products]);

  useEffect(() => {
    if (sortedUpsellProducts) {
      const anyUpsellProductsAvailable = sortedUpsellProducts.some(
        (product) =>
          isNonEmptyArray(product.timeSlots) || product.glkProduct.productType === WebshopProductType.STANDARD,
      );
      setAnyUpsellProductsAvailable(anyUpsellProductsAvailable);
    }
  }, [sortedUpsellProducts, setAnyUpsellProductsAvailable]);

  return (
    <ul className={styles.upsellList}>
      {isLoadingTimeSlots ? (
        <p className="heading-l" data-contentful-label-id="loading">
          {t("loading")}
        </p>
      ) : (
        sortedUpsellProducts
          .filter(
            (product) =>
              product &&
              (isNonEmptyArray(product.timeSlots) || product.glkProduct.productType === WebshopProductType.STANDARD),
          )
          .map((product) => {
            return (
              <li key={product.productId}>
                <UpsellItem
                  upsellProductId={product.productId}
                  selectedUpsellProduct={selectedUpsellProducts?.get(product.productId)}
                  selectedEntryTimeSlot={selectedEntryTimeSlot}
                  timeSlots={product.timeSlots ?? []}
                  selectedDate={selectedDate.date}
                  totalGroupSize={totalGroupSize}
                  isDisabled={product.disabled}
                  dispatch={dispatch}
                />
              </li>
            );
          })
      )}
    </ul>
  );
};

export default UpsellList;
