// @ts-strict-ignore
import styles from "./select-jetpass.module.less";
import { PrimaryButton, GhostButton } from "@/core/components/primitives/parks-button/parks-button";
import {
  ActionType,
  Step,
  Guest,
  SelectablePass,
  StepProps,
} from "@/core/types/state/group-admission/group-admission-types";
import { DateHelper, GroupAdmissionHelper, insertIntoString, isNonEmptyArray } from "@/core/helpers";
import { mapAdmissionGuestToJetpassGuest, mapJetpassGuestToGuestDTO } from "@/core/helpers/jetpass-helper";
import { useTranslation } from "react-i18next";
import useFocus from "@/core/hooks/use-focus";
import { useEffect, useState } from "react";
import { useJetpassModalContext } from "@/core/contexts/jetpass-modal-context";
import { useProducts } from "@/core/hooks/product-hooks";

type SelectJetpassProps = {
  stepWrapperRef: HTMLElement;
  guests: Array<Guest>;
  selectedDate: Date;
  selectedEntryTime: SelectablePass;
  jetpassMaxLimit?: number;
} & StepProps;

const PassRow = ({ pass }: { pass: SelectablePass }) => {
  return (
    <li className={[styles.passRow, "p_small"].join(" ")}>
      {DateHelper.toStringTimeHHMM(pass.timeSlotFrom)} • {pass.attractionName}
    </li>
  );
};

const GuestRow = ({ guest, index }: { guest: Guest; index: number }) => {
  const { t } = useTranslation();
  const jetPasses = guest.admissionProduct?.selectedJetpasses ?? [];

  return (
    <div className={styles.guestRowWrapper}>
      <ul className={styles.passList}>
        <p className={styles.guestName}>{guest.name ? guest.name : `${t("guest")} ${index}`}</p>
        {isNonEmptyArray(jetPasses) && jetPasses.map((pass) => <PassRow key={pass.timeSlotId} pass={pass} />)}
      </ul>
    </div>
  );
};

const anyGuestHasJetPassSelected = (guests: Array<Guest>): boolean => {
  return guests.some((guest) => {
    const selectedJetPasses = guest?.admissionProduct?.selectedJetpasses ?? [];

    return isNonEmptyArray(selectedJetPasses);
  });
};

const SelectJetpass = ({
  stepWrapperRef,
  onClickBack,
  stepIndex,
  guests,
  selectedDate,
  selectedEntryTime,
  jetpassMaxLimit,
  dispatch,
}: SelectJetpassProps) => {
  const [jetpassModalContext, setJetpassModalContext] = useJetpassModalContext();
  const { t } = useTranslation();

  const [activatedJetpassModal, setActivatedJetpassModal] = useState(false);
  const [focusRef, setFocus] = useFocus<HTMLDivElement>();

  const { productsById: admissionProducts } = useProducts(guests.map((guest) => guest.admissionProduct.id));

  useEffect(() => {
    if (!jetpassModalContext.showJetPassModal && activatedJetpassModal) {
      setFocus();
      setActivatedJetpassModal(false);
    }
  }, [jetpassModalContext, activatedJetpassModal]);

  const onStepComplete = () => {
    GroupAdmissionHelper.scrollAndCompleteStep(stepWrapperRef, Step.SELECT_JETPASS, dispatch, true);
  };

  const onSelectJetpassComplete = (selectionData: any) => {
    const guestDTOs = isNonEmptyArray(selectionData.guests)
      ? selectionData.guests.map((guest) => mapJetpassGuestToGuestDTO(guest))
      : [];

    setFocus();
    setActivatedJetpassModal(false);

    dispatch({ type: ActionType.ADD_JETPASSES_TO_GUESTS, payload: { jetpassGuests: guestDTOs } });
    onStepComplete();
  };

  const onClickSelectJetpass = () => {
    const jetpassGuests = guests
      .map((guest) => mapAdmissionGuestToJetpassGuest(guest, 0, guest.admissionProduct.numberOfJetpassIncluded))
      .map(({ product, ...rest }) => ({
        ...rest,
        product: {
          ...product,
          productName: admissionProducts.get(product.glkId)?.name || "",
        },
      }));
    setJetpassModalContext({
      showJetPassModal: true,

      onSelectJetpassComplete: (selectionData) => onSelectJetpassComplete(selectionData),
      jetPassDate: selectedDate,
      guests: jetpassGuests,
      jetPassOptions: {
        disableIntro: true,
        enableBackButton: false,
        filterOutTimesBefore: selectedEntryTime ? selectedEntryTime.timeSlotFrom : undefined,
      },
    });
    setActivatedJetpassModal(true);
  };

  const hasJetPassSelected = anyGuestHasJetPassSelected(guests);
  const guestsHasExeededJetpassLimit = GroupAdmissionHelper.hasGuestsExeededJetpassLimit(guests, jetpassMaxLimit);

  return (
    <div className={styles.wrapper}>
      {guestsHasExeededJetpassLimit && (
        <>
          <h3
            className={`heading-s ${styles.heading}`}
            data-contentful-label-id="selectJetpassStepHeadingTooManyGuests"
          >
            {t("selectJetpassStepHeadingTooManyGuests")}
          </h3>
          <p className={styles.description} data-contentful-label-id="selectJetpassStepDescriptionTooManyGuests">
            {t("selectJetpassStepDescriptionTooManyGuests")}
          </p>
          <p data-contentful-label-id="selectJetpassStepTermsTooManyGuests">
            {t("selectJetpassStepTermsTooManyGuests")}
          </p>

          <div ref={focusRef} tabIndex={-1} className={styles.buttonWrapper}>
            {stepIndex > 0 && (
              <PrimaryButton
                isFullWidth={true}
                onClick={onClickBack}
                className={styles.prevButton}
                label={t("previous")}
                contentfulLabelId="previous"
                complementary={true}
              />
            )}
            <PrimaryButton
              isFullWidth={true}
              onClick={onStepComplete}
              isDisabled={false}
              className={styles.skipStepButton}
              label={t("nextStep")}
              contentfulLabelId="nextStep"
              testId="skip-jetpass-button"
            />
          </div>
        </>
      )}
      {!guestsHasExeededJetpassLimit && (
        <>
          {!hasJetPassSelected && (
            <>
              <h3 className={`heading-s ${styles.heading}`} data-contentful-label-id="selectJetpassStepHeading">
                {t("selectJetpassStepHeading")}
              </h3>
              <p className={styles.description} data-contentful-label-id="selectJetpassStepDescription">
                {insertIntoString(t("selectJetpassStepDescription"), "2")}
              </p>
              <p data-contentful-label-id="selectJetpassStepTerms">{t("selectJetpassStepTerms")}</p>
            </>
          )}
          {hasJetPassSelected && (
            <ul className={styles.guestList}>
              {guests.map((guest, i) => (
                <li key={guest.id} className={styles.guestListItem}>
                  <GuestRow guest={guest} index={i + 1} />
                </li>
              ))}
            </ul>
          )}
          <div ref={focusRef} tabIndex={-1} className={styles.buttonWrapper}>
            {stepIndex > 0 && (
              <PrimaryButton
                isFullWidth={true}
                onClick={onClickBack}
                className={styles.prevButton}
                label={t("previous")}
                contentfulLabelId="previous"
                complementary={true}
              />
            )}
            <PrimaryButton
              isFullWidth={true}
              onClick={onClickSelectJetpass}
              label={hasJetPassSelected ? t("modify") : t("selectJetpassSelectRides")}
              contentfulLabelId={hasJetPassSelected ? "modify" : "selectJetpassSelectRides"}
            />
          </div>
          <GhostButton
            isFullWidth={true}
            onClick={onStepComplete}
            isDisabled={false}
            className={styles.skipStepButton}
            label={hasJetPassSelected ? t("nextStep") : t("selectJetpassSelectRidesLater")}
            contentfulLabelId={hasJetPassSelected ? "nextStep" : "selectJetpassSelectRidesLater"}
            testId="skip-jetpass-button"
          />
        </>
      )}
    </div>
  );
};

export default SelectJetpass;
