import { useEffect, useState } from "react";
import styles from "./select-entry-time.module.less";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import {
  ActionType,
  Step,
  Guest,
  StepProps,
  VisitDate,
  UpsellProductsForDate,
  SelectablePass,
  GroupAdmissionState,
} from "@/core/types/state/group-admission/group-admission-types";
import { DateHelper, createDate, GroupAdmissionHelper, isNonEmptyArray, throwError } from "@/core/helpers";
import { TimeSlotList } from "@/core/components/modules/time-slot-list/time-slot-list";
import { ITimeSlot, IGLKMyParksEntranceWithProductId } from "@/core/types/time-slots";
import TimeSlotService from "@/core/services/time-slot-service";
import { AnimatePresence } from "framer-motion";
import DialogModal from "@/core/components/primitives/dialog-modal/dialog-modal";
import { uniqueId } from "lodash-es";
import { EntryVariant, TimeLimits } from "@/core/types/services/purchase-flow-service-types";
import { useTranslation } from "react-i18next";
import useFocus from "@/core/hooks/use-focus";
import { ButtonRow } from "../../components/button-row";
import { useProducts } from "@/core/hooks/product-hooks";

type InformationModalProps = {
  bodyText: JSX.Element;
  selectedEntryTimeArray: Array<SelectablePass>;
  removeSelectedJetpasses: boolean;
  selectedUpsellProductsBeforeEntryTime: UpsellProductsForDate[];
};

type SelectEntryTimeProps = {
  selectedVariant: EntryVariant;
  selectedDates: Map<string, VisitDate>;
  guests: Array<Guest>;
  quantity: GroupAdmissionState["quantity"];
  stepWrapperRef: HTMLElement;
} & StepProps;

const filterTimeSlots = (timeSlots: Array<ITimeSlot>, timeLimits: TimeLimits): Array<ITimeSlot> => {
  const futureTimeSlots = timeSlots.filter((timeSlot) => !DateHelper.hasDatePassed(timeSlot.timeSlotFrom));
  if (!timeLimits) {
    return futureTimeSlots;
  }

  const timeSlotsWithinTimeLimit = futureTimeSlots.filter((timeSlot) => {
    const timeSlotFromDate = createDate(timeSlot.timeSlotFrom);

    const firstEntryTime = timeLimits.firstEntryTime;
    const firstEntryTimeDate = firstEntryTime
      ? createDate(DateHelper.toStringYYYYMMDD(timeSlotFromDate) + "T" + firstEntryTime)
      : null;

    const lastEntryTime = timeLimits.lastEntryTime;
    const lastEntryTimeDate = lastEntryTime
      ? createDate(DateHelper.toStringYYYYMMDD(timeSlotFromDate) + "T" + lastEntryTime)
      : null;

    return DateHelper.isDateInDateSpan(timeSlotFromDate, firstEntryTimeDate, lastEntryTimeDate, "minute");
  });

  return timeSlotsWithinTimeLimit;
};

const filterEntrances = (
  entrances: Array<IGLKMyParksEntranceWithProductId>,
  timeLimit: TimeLimits,
): Array<IGLKMyParksEntranceWithProductId> => {
  const filteredEntrances = entrances.map((entrance) => {
    return {
      ...entrance,
      timeSlots: filterTimeSlots(
        entrance.timeSlots.map((timeSlot) => ({ ...timeSlot, productId: entrance.productId })),
        timeLimit,
      ),
    };
  });
  return filteredEntrances;
};

const InformationModalBodyElement = ({
  hasSelectedJetpassesBeforeEntryTime,
  selectedUpsellProductsBeforeEntryTime,
}: {
  hasSelectedJetpassesBeforeEntryTime: boolean;
  selectedUpsellProductsBeforeEntryTime: Array<UpsellProductsForDate>;
}) => {
  const { t } = useTranslation();
  const { productsById } = useProducts(
    selectedUpsellProductsBeforeEntryTime.flatMap((upsellProductForDate) =>
      [...upsellProductForDate.upsellProducts.values()].map((upsellProduct) => upsellProduct.productId),
    ),
  );
  return (
    <div className={styles.informationModalBodyWrapper}>
      <p className={styles.informationModalBodyText} data-contentful-label-id="selectEntryTimeStepDialogChangeBodyText">
        {t("selectEntryTimeStepDialogChangeBodyText")}
      </p>
      <ul className={styles.informationModalList}>
        {hasSelectedJetpassesBeforeEntryTime && (
          <li className={styles.informationModalListItem} data-contentful-label-id="jetpass">
            {t("jetpass")}
          </li>
        )}
        {isNonEmptyArray(selectedUpsellProductsBeforeEntryTime) &&
          selectedUpsellProductsBeforeEntryTime.map((upsellProductForDate) => {
            const dateString = DateHelper.toStringMMDDWeekday(upsellProductForDate.date);
            return (
              <div key={uniqueId()}>
                <p>{dateString}</p>
                {[...upsellProductForDate.upsellProducts.values()].map((upsellProduct) => {
                  return (
                    <li key={upsellProduct.productId} className={styles.informationModalListItem}>
                      {productsById.get(upsellProduct.productId)?.name}
                    </li>
                  );
                })}
              </div>
            );
          })}
      </ul>
    </div>
  );
};

const isSelectedDatesIsEqualToPrevSelectedDates = (
  selectedDates: Map<string, VisitDate>,
  prevSelectedDates: Array<string>,
): boolean => {
  if (!isNonEmptyArray(prevSelectedDates)) {
    return false;
  }

  for (const date of prevSelectedDates) {
    if (!selectedDates.has(date)) {
      return false;
    }
  }

  return true;
};

const SelectEntryTime = ({
  onClickBack,
  stepIndex,
  selectedDates,
  selectedVariant,
  guests,
  quantity,
  dispatch,
  stepWrapperRef,
}: SelectEntryTimeProps) => {
  const [entrances, setEntrances] = useState<IGLKMyParksEntranceWithProductId[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [apiError] = useState(null);
  const [informationModalProps, setInformationModalProps] = useState<InformationModalProps | null>(null);
  const [prevSelectedDates, setPrevSelectedDates] = useState<Array<string>>([]);
  const { t } = useTranslation();
  const [focusRef, setFocus] = useFocus<HTMLDivElement>();

  const [firstVisitDateInSelectedDates] = [...selectedDates.values()];
  const selectedEntryTimeOnFirstVisitDate = firstVisitDateInSelectedDates
    ? firstVisitDateInSelectedDates.selectedEntryTime
    : null;

  const { productsById: upsellProducts } = useProducts(
    [...selectedDates.values()].flatMap((visitDate) =>
      [...visitDate.selectedUpsellProducts.values()].map((p) => p.productId),
    ),
  );

  useEffect(() => {
    if (
      !selectedVariant ||
      selectedDates.size === 0 ||
      isSelectedDatesIsEqualToPrevSelectedDates(selectedDates, prevSelectedDates)
    ) {
      return;
    }

    setIsLoading(true);
    const glkId = guests?.[0]?.admissionProduct?.id ?? null;

    const getEntrancesAndJetpassTimeslotsPromises = [...selectedDates.keys()].map((date) =>
      TimeSlotService.getEntrancesAndJetpassTimeslots(glkId, DateHelper.toStringYYYYMMDD(date)),
    );

    Promise.all(getEntrancesAndJetpassTimeslotsPromises)
      .then((response) => {
        const entranceAndJetpassTimeslotsArray = response.flatMap((responseForDate) => {
          const entrances = responseForDate?.response?.timePassTimeSlots ?? [];
          const timeLimits = guests?.[0]?.admissionProduct?.timeLimits ?? null;
          const filteredEntrances = filterEntrances(entrances, timeLimits);
          return filteredEntrances;
        });
        setPrevSelectedDates([...selectedDates.keys()]);
        setEntrances(entranceAndJetpassTimeslotsArray);
      })
      .catch((error) => {
        console.error("getEntrancesAndJetpassTimeslots error: ", error);
      })
      .finally(() => {
        setIsLoading(false);
      });
  }, [selectedDates, selectedVariant]);

  const onClickAcceptChange = (informationModalProps: InformationModalProps) => {
    const { selectedEntryTimeArray, removeSelectedJetpasses, selectedUpsellProductsBeforeEntryTime } =
      informationModalProps;
    dispatch({
      type: ActionType.SELECT_ENTRY_TIME,
      payload: {
        selectedEntryTime: selectedEntryTimeArray,
        removeSelectedJetpasses: removeSelectedJetpasses,
        updatedSelectedUpsellProducts: selectedUpsellProductsBeforeEntryTime,
      },
    });
    closeDialog();
  };

  const onClickSelectTimeSlot = (
    timeSlot: ITimeSlot,
    productId: number,
    attractionId: number,
    attractionName: string,
  ) => {
    const timeSlotsPerVisitDate = GroupAdmissionHelper.getSelectedTimeSlotsFromEntrancesArray(
      entrances,
      timeSlot.timeSlotFrom,
    );
    const selectedEntryTimePerDate = timeSlotsPerVisitDate.map((timeSlotPerVisitDate) =>
      GroupAdmissionHelper.mapTimeSlotToSelectablePass(timeSlotPerVisitDate, productId, attractionId, attractionName),
    );
    let hasSelectedJetpassesBeforeEntryTime = false;
    const selectedUpsellProductsBeforeEntryTime = new Array<UpsellProductsForDate>();

    for (const selectedEntryTimeForDate of selectedEntryTimePerDate) {
      const dateKey = DateHelper.toStringYYYYMMDD(selectedEntryTimeForDate.timeSlotFrom);

      // Kolla om man valt jetpass för dagen
      const hasGuestJetpassesForDate = guests.some((guest) => {
        const jetpassForDate = guest.admissionProduct.selectedJetpasses.find((jetpass) => {
          return DateHelper.toStringYYYYMMDD(jetpass.timeSlotFrom) === dateKey;
        });
        return isNonEmptyArray(jetpassForDate);
      });

      // Kolla om jetpass för dagen är innan vald entrétid
      // - Spara undan dessa jetpass -> resetta i reducer???
      if (hasGuestJetpassesForDate) {
        hasSelectedJetpassesBeforeEntryTime = GroupAdmissionHelper.hasSelectedJetpassesBeforePickedEntryTime(
          guests,
          selectedEntryTimeForDate.timeSlotFrom,
        );
      }

      // Kolla om man valt mersälj för dagen
      const visitDate = selectedDates.get(dateKey) ?? throwError("Visit date not found for dateKey: " + dateKey);
      const hasSelectedUpsellProductsForDate = visitDate.selectedUpsellProducts.size > 0;

      // Kolla om någon mersälj har tidsslott innan vald entrétid
      // - Spara undan dessa -> resetta i reducer senare
      if (hasSelectedUpsellProductsForDate) {
        selectedUpsellProductsBeforeEntryTime.push(
          ...GroupAdmissionHelper.getSelectedUpsellProductsBeforePickedEntryTime(
            visitDate.selectedUpsellProducts,
            upsellProducts,
            selectedEntryTimeForDate.timeSlotFrom,
          ),
        );
      }
    }

    if (hasSelectedJetpassesBeforeEntryTime || isNonEmptyArray(selectedUpsellProductsBeforeEntryTime)) {
      setInformationModalProps({
        bodyText: (
          <InformationModalBodyElement
            hasSelectedJetpassesBeforeEntryTime={hasSelectedJetpassesBeforeEntryTime}
            selectedUpsellProductsBeforeEntryTime={selectedUpsellProductsBeforeEntryTime}
          />
        ),
        selectedEntryTimeArray: selectedEntryTimePerDate,
        removeSelectedJetpasses: hasSelectedJetpassesBeforeEntryTime,
        // Låt reducern hantera förändringen av selectedUpsellProducts per datum
        selectedUpsellProductsBeforeEntryTime: selectedUpsellProductsBeforeEntryTime,
      });
    } else {
      dispatch({ type: ActionType.SELECT_ENTRY_TIME, payload: { selectedEntryTime: selectedEntryTimePerDate } });
    }
  };

  function closeDialog() {
    setFocus();
    setInformationModalProps(null);
  }

  const onClickStepComplete = () => {
    GroupAdmissionHelper.scrollAndCompleteStep(stepWrapperRef, Step.SELECT_ENTRY_TIME, dispatch);
  };

  const timeSlots = entrances?.[0]?.timeSlots ?? [];
  const attractionId = entrances?.[0]?.attractionId ?? null;
  const productId = entrances?.[0]?.productId ?? null;
  const attractionName = entrances?.[0]?.attractionName ?? null;
  const totalGuestQuantity = quantity.size && [...quantity.values()].reduce((prev, curr) => prev + curr);

  return (
    <div ref={focusRef} tabIndex={-1} className={styles.wrapper}>
      <div className={`${styles.innerWrapper} ${isLoading || apiError ? styles.faded : ""}`}>
        <h4 className={`subtitle ${styles.heading}`} data-contentful-label-id="selectEntryTimeStepTitle">
          {t("selectEntryTimeStepTitle")}
        </h4>
        {selectedVariant && selectedVariant.numberOfDays > 1 ? (
          <p className={styles.description} data-contentful-label-id="selectEntryTimeStepDescriptionMultipleDays">
            {t("selectEntryTimeStepDescriptionMultipleDays")}
          </p>
        ) : (
          <p className={styles.description} data-contentful-label-id="selectEntryTimeStepDescription">
            {t("selectEntryTimeStepDescription")}
          </p>
        )}
        <TimeSlotList
          timeSlots={timeSlots.map((timeSlot) => ({
            ...timeSlot,
            productId: productId,
          }))}
          attractionId={attractionId}
          productId={productId}
          attractionName={attractionName}
          heading=""
          onClick={onClickSelectTimeSlot}
          showMoreThreshhold={12}
          selectedTimeSlotId={selectedEntryTimeOnFirstVisitDate ? selectedEntryTimeOnFirstVisitDate.timeSlotId : null}
          quantity={totalGuestQuantity}
        />
        <ButtonRow
          stepIndex={stepIndex}
          onClickBack={onClickBack}
          onClickStepComplete={onClickStepComplete}
          nextDisabled={!selectedEntryTimeOnFirstVisitDate}
        />
      </div>

      {isLoading && (
        <div className={styles.loader}>
          <h4 data-contentful-label-id="selectEntryTimeStepLoadingEntryTimes">
            {t("selectEntryTimeStepLoadingEntryTimes")}
          </h4>
        </div>
      )}
      {apiError && (
        <div className={styles.loader}>
          <h4 data-contentful-label-id="selectEntryTimeStepErrorGetEntryTimes">
            {t("selectEntryTimeStepErrorGetEntryTimes")}
          </h4>
          <PrimaryButton
            isFullWidth={true}
            className={styles.continueButton}
            label={t("tryAgain")}
            contentfulLabelId="tryAgain"
          />
        </div>
      )}
      <AnimatePresence>
        {informationModalProps && (
          <DialogModal
            headingText={t("selectEntryTimeStepDialogHeadingText")}
            bodyText={informationModalProps.bodyText}
            primaryButtonText={t("selectEntryTimeStepDialogConfirmChange")}
            primaryButtonAction={() => onClickAcceptChange(informationModalProps)}
            secondaryButtonText={t("cancel")}
            secondaryButtonAction={closeDialog}
            onCloseFunction={closeDialog}
            contentfulLabelIds={{
              headingText: "selectEntryTimeStepDialogHeading",
              bodyText: "selectEntryTimeStepDialogBodyText",
              confirmChange: "selectEntryTimeStepDialogConfirmChange",
              cancelChange: "cancel",
            }}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

export default SelectEntryTime;
