import styles from "./promotion-banner.module.less";
import { BannerData } from "@/core/types/state/group-admission/group-admission-types";
import RichText from "@/core/components/primitives/rich-text/rich-text";
import Link from "@/core/components/primitives/link/link";

const BannerContent = ({ bannerText, bannerImage }: BannerData) => {
  return (
    <>
      <div className={styles.bannerText}>
        <RichText richText={bannerText} />
      </div>
      {bannerImage && <img className={styles.bannerImage} src={bannerImage} alt="" />}
    </>
  );
};

const PromotionBanner = ({ bannerText, bannerLink, bannerImage, openBannerLinkInNewTab }: BannerData) => {
  if (bannerLink) {
    return (
      <Link className={styles.bannerWrapper} contentfulLink={bannerLink} openInNewTab={openBannerLinkInNewTab ?? false}>
        <BannerContent bannerText={bannerText} bannerImage={bannerImage} />
      </Link>
    );
  } else {
    return (
      <div className={styles.bannerWrapper}>
        <BannerContent bannerText={bannerText} bannerImage={bannerImage} />
      </div>
    );
  }
};

export default PromotionBanner;
