import { CartRequestCartItem, CartResponseV2CartItem } from "@parksandresorts/webapiproxy-types";
import { Translation } from "@/core/labels/i18n";

export const isSameCartItem = <T extends CartResponseV2CartItem | CartRequestCartItem>(
  existingCartItem: T,
  newCartItem: CartRequestCartItem,
) => existingCartItem.productId === newCartItem.productId && existingCartItem.visitorName === newCartItem.visitorName;

/**
 * cartItemHasChanged figures out if a cart item has changed.
 * If so, it indicates whether if it can be patched, if subitems are added or removed, or if the entire cartItem needs to be removed and re-added.
 */
export const cartItemHasChanged = <T extends CartResponseV2CartItem | CartRequestCartItem>(
  existingCartItem: T,
  newCartItem: CartRequestCartItem,
): null | "patch" | "re-add" | { addedSubItems: Array<CartRequestCartItem>; removedSubItems: Array<T> } => {
  // we cannot patch the slot field
  const slotFieldHasChanged = existingCartItem.slot?.slotId !== newCartItem.slot?.slotId;
  if (slotFieldHasChanged) {
    return "re-add";
  }
  // The only patchable fields are quantity and visitorName
  const patchableFieldsHaveChanged =
    existingCartItem.quantity !== newCartItem.quantity || existingCartItem.visitorName !== newCartItem.visitorName;

  const subItems = (existingCartItem.subItems ?? []) as Array<T>; // This cast is necessary to fix the ts(2345) error. We know the types are correct.
  const subItemsDiff = diffCartItems<T>(subItems, newCartItem.subItems ?? []);
  const subItemsHaveChanged = subItemsDiff !== "noop";

  if (subItemsHaveChanged && patchableFieldsHaveChanged) {
    // If both subitems and patchable fields have changed, we need to re-add the entire cartItem, as we don't support updating both at the same time
    return "re-add";
  }
  if (patchableFieldsHaveChanged) {
    return "patch";
  }
  if (!subItemsHaveChanged) {
    return null;
  }
  // invariant: At this point, we know that _only_ subitems have changed

  if (subItemsDiff === "new") {
    return { addedSubItems: newCartItem.subItems!, removedSubItems: [] };
  }
  const { added, removed, updated } = subItemsDiff;
  for (const [previousItem, newItem] of updated) {
    // There is no endpoint for updating a specific subitem, so we have to remove and re-add the subItem
    removed.push(previousItem);
    added.push(newItem);
  }
  return {
    addedSubItems: added,
    removedSubItems: removed,
  };
};

export function diffCartItems<T extends CartResponseV2CartItem | CartRequestCartItem>(
  previousCartItems: Array<T>,
  newCartItems: Array<CartRequestCartItem>,
):
  | "noop"
  | "new"
  | {
      added: Array<CartRequestCartItem>;
      removed: Array<T>;
      updated: Array<[T, CartRequestCartItem]>;
    } {
  if (previousCartItems.length === 0 && newCartItems.length === 0) {
    return "noop";
  }
  if (previousCartItems.length === 0) {
    return "new";
  }

  const {
    newCartItems: added,
    removed,
    existing,
  } = previousCartItems.reduce<{
    newCartItems: Array<CartRequestCartItem>;
    removed: Array<T>;
    existing: Array<[T, CartRequestCartItem]>;
  }>(
    ({ newCartItems, removed, existing }, prevItem) => {
      const found = newCartItems.find((newItem) => isSameCartItem(prevItem, newItem));
      if (found) {
        return {
          newCartItems: newCartItems.filter((newItem) => newItem !== found),
          removed,
          existing: [...existing, [prevItem, found]],
        };
      }
      return { newCartItems, removed: [...removed, prevItem], existing };
    },
    { newCartItems, removed: [], existing: [] },
  );

  const updated = existing.filter(([prevItem, newItem]) => cartItemHasChanged(prevItem, newItem));

  if (added.length + removed.length + updated.length === 0) {
    return "noop";
  }

  return { added, removed, updated };
}

export function getSummaryItemSubtitleForCartItem(cartItem: CartResponseV2CartItem, t: Translation) {
  if (!cartItem.data?.cardHolderInformationV1) {
    return undefined;
  }
  return t("owner", {
    firstName: cartItem.data.cardHolderInformationV1.firstName,
    lastName: cartItem.data.cardHolderInformationV1.lastName,
  });
}
