// @ts-strict-ignore
import { useMemo, useState } from "react";
import {
  GroupAdmissionState,
  Guest,
  PurchaseFlowDate,
  Step,
  StepProps,
  VisitDate,
} from "@/core/types/state/group-admission/group-admission-types";
import styles from "./upsell.module.less";
import UpsellList from "./upsell-list/upsell-list";
import { sum } from "lodash-es";
import { EntryVariant, UpsellProduct as UpsellProductApi } from "@/core/types/services/purchase-flow-service-types";
import { capitalizeFirstLetter, DateHelper, GroupAdmissionHelper } from "@/core/helpers";
import { useTranslation } from "react-i18next";
import { ButtonRow } from "../../components/button-row";

type UpsellProps = {
  upsellProducts: Array<UpsellProductApi>;
  selectedDates: Map<string, [VisitDate, PurchaseFlowDate]>;
  quantity: GroupAdmissionState["quantity"] | null;
  guests: Array<Guest>;
  selectedVariant: EntryVariant;
  stepWrapperRef: HTMLElement;
} & StepProps;

const Upsell = ({
  onClickBack,
  stepIndex,
  upsellProducts,
  selectedDates,
  quantity,
  guests,
  selectedVariant,
  stepWrapperRef,
  dispatch,
}: UpsellProps) => {
  const totalGroupSize = useMemo(() => sum([...quantity.values()]), [quantity]);
  const [anyUpsellProductsAvailable, setAnyUpsellProductsAvailable] = useState(true);
  const { t } = useTranslation();

  const isAnyUpsellProductsAvailable = (value: boolean) => setAnyUpsellProductsAvailable(value);

  const onClickStepComplete = () => {
    GroupAdmissionHelper.scrollAndCompleteStep(stepWrapperRef, Step.UPSELL, dispatch);
  };

  return (
    <div className={styles.wrapper}>
      <div className={styles.innerWrapper}>
        <div className={styles.textWrapper}>
          <h3 className={`heading-xs ${styles.heading}`} data-contentful-label-id="upsellStepHeading">
            {t("upsellStepHeading")}
          </h3>
          {anyUpsellProductsAvailable && (
            <p className={styles.description} data-contentful-label-id="upsellStepDescription">
              {t("upsellStepDescription")}
            </p>
          )}
          {!anyUpsellProductsAvailable && (
            <p className={styles.description} data-contentful-label-id="upsellStepNoProductsDescription">
              {t("upsellStepNoProductsDescription")}
            </p>
          )}
        </div>
        {[...selectedDates.values()].map(([visitDate, calendarData]) => {
          return (
            <div key={visitDate.date.toString()}>
              {anyUpsellProductsAvailable && (
                <h4 className={`heading-xs ${styles.upsellItemListHeading}`}>
                  {capitalizeFirstLetter(DateHelper.toStringMMDDWeekday(visitDate.date))}
                </h4>
              )}
              <UpsellList
                upsellProductIds={upsellProducts.map((p) => p.id)}
                selectedDate={calendarData}
                selectedEntryTimeSlot={visitDate.selectedEntryTime}
                selectedVariant={selectedVariant}
                totalGroupSize={totalGroupSize}
                selectedUpsellProducts={visitDate.selectedUpsellProducts}
                guests={guests}
                setAnyUpsellProductsAvailable={isAnyUpsellProductsAvailable}
                dispatch={dispatch}
              />
            </div>
          );
        })}
        <div className={styles.buttonWrapper}>
          <ButtonRow stepIndex={stepIndex} onClickBack={onClickBack} onClickStepComplete={onClickStepComplete} />
        </div>
      </div>
    </div>
  );
};

export default Upsell;
