// @ts-strict-ignore
import { Reducer } from "react";
import {
  Action,
  ActionType,
  Step,
  GroupAdmissionState,
  Guest,
  StepData,
  GuestDTO,
  SelectedUpsellProduct,
  VisitDate,
  SelectablePass,
  UpsellProductsForDate,
  ProductWithQuantity,
  GroupAdmissionSharedState,
} from "../../types/state/group-admission/group-admission-types";
import { createDate, DateHelper, GroupAdmissionHelper, isNonEmptyArray } from "@/core/helpers";
import { uniqueId, uniqBy } from "lodash-es";
import { EntryVariant, Product, VisitorCategory } from "@/core/types/services/purchase-flow-service-types";
import { ITimeSlot } from "@/core/types/time-slots";

const GroupAdmissionInitialState: GroupAdmissionSharedState = {
  steps: null,
  activeStep: null,
  quantity: new Map<VisitorCategory["id"], number>(),
  isCompleted: new Map<Step, boolean>(),
  selectedDateOpeningHours: null,
  selectedDates: new Map<string, VisitDate>(),
  selectedDate: null,
  selectedDateProducts: [],
  variantsForSelectedDate: [],
  selectedMonth: createDate(),
  selectedVariant: null,
  guests: [],
  variants: null,
  entryVariantType: null,
  preSelectedDate: false,
  isDisabledStep: new Map<Step, boolean>(),
};

const getSelectedDates = (date: Date) => {
  const selectedDates = new Map<string, VisitDate>();
  if (date) {
    selectedDates.set(DateHelper.toStringYYYYMMDD(date), {
      date: date,
      selectedEntryTime: null,
      selectedUpsellProducts: new Map<number, SelectedUpsellProduct>(),
    });
  }
  return selectedDates;
};

const getGuestsFromVariantSelection = (
  quantity: GroupAdmissionState["quantity"],
  products: Array<Product>,
  selectedVariant?: string,
): Array<Guest> => {
  const guests: Array<Guest> = [];

  const filteredProducts = products.filter((product) => selectedVariant === product?.productMetadata?.entryVariant);

  const uniqueProducts = uniqBy(filteredProducts, "productId");

  for (const product of uniqueProducts) {
    const visitorCategory = product?.productMetadata?.visitorCategory ?? null;
    if (quantity.has(visitorCategory)) {
      const quantityForCategory = quantity.get(visitorCategory);
      guests.push(...createGuestsFromSelection(quantityForCategory, product, visitorCategory));
    }
  }

  return guests;
};

const getGuestsFromTicketSelection = (products: Array<ProductWithQuantity>): Array<Guest> => {
  return products.flatMap((product) => {
    const visitorCategory = product?.productMetadata?.visitorCategory ?? null;

    const quantity = product.quantity;

    return createGuestsFromSelection(quantity, product, visitorCategory);
  });
};

const createGuestsFromSelection = (quantity: number, product: Product, visitorCategory?: VisitorCategory["id"]) => {
  const guests: Array<Guest> = [];
  for (let i = 0; i < quantity; i++) {
    guests.push({
      id: uniqueId("guest-"),
      name: null,
      visitorCategory: visitorCategory,
      admissionProduct: {
        id: product.productId,
        dateSlotId: product.dateSlot?.dateSlotId ?? null,
        dateSlot: product?.dateSlot ?? null,
        timePassRequired: product.timePassRequired,
        numberOfJetpassIncluded: product.productMetadata?.numberOfJetPassIncluded ?? 0,
        timeLimits: product.productMetadata?.timeLimits ?? null,
        selectedJetpasses: [],
        selectedMandatoryJetpass: null,
      },
    });
  }
  return guests;
};

const removeSelectedJetpasses = (guests: Array<Guest>): Array<Guest> => {
  const updatedGuests = guests.map((guest) => {
    return {
      ...guest,
      name: null,
      admissionProduct: {
        ...guest.admissionProduct,
        selectedJetpasses: [],
      },
    };
  });
  return updatedGuests;
};

const removeIsCompleteForSubsequentSteps = (
  activeStep: number,
  steps: Array<StepData>,
  isCompleted: Map<Step, boolean>,
): Map<Step, boolean> => {
  const isCompletedCopy = new Map(isCompleted);
  for (let i = activeStep + 1; i < steps.length; i++) {
    isCompletedCopy.set(steps[i].stepType, false);
  }
  return isCompletedCopy;
};

const selectedDateAndVariantHasQuantityForGroup = (
  selectedDateProducts: Array<Product>,
  selectedVariant: EntryVariant,
  quantityMap: GroupAdmissionState["quantity"],
): boolean => {
  const productsForVariant = selectedDateProducts.filter(
    (product) => product?.productMetadata?.entryVariant === (selectedVariant?.id ?? null),
  );

  if (!isNonEmptyArray(productsForVariant)) {
    return false;
  }

  for (const product of productsForVariant) {
    const stateQuantity = quantityMap.get(product.productMetadata.visitorCategory);
    const productQuantity = product.dateSlot?.quantity ?? 0;
    if (productQuantity < stateQuantity) {
      return false;
    }
  }

  return true;
};

const getSelectedDatesMap = (selectedDate: Date, numberOfDays = 1): Map<string, VisitDate> => {
  if (!selectedDate) {
    return undefined;
  }

  const dateMap = new Map<string, VisitDate>();
  for (let i = 0; i < numberOfDays; i++) {
    const newDate = DateHelper.addDays(selectedDate, i);
    dateMap.set(DateHelper.toStringYYYYMMDD(newDate), {
      date: newDate,
      selectedEntryTime: null,
      selectedUpsellProducts: new Map<number, SelectedUpsellProduct>(),
    });
  }
  return dateMap;
};

const findDisabledSteps = (
  isDisabledStep: Map<Step, boolean>,
  steps: Array<StepData>,
  guests: Array<Guest>,
): Map<Step, boolean> => {
  const disabledSteps = new Map(isDisabledStep);

  if (steps.some((step) => step.stepType === Step.SELECT_JETPASS)) {
    const hasGuests = guests.length > 0;
    const guestsHasNoJetpasses = guests?.every((guest) => guest.admissionProduct.numberOfJetpassIncluded === 0);
    const shouldStepBeDisabled = hasGuests && guestsHasNoJetpasses;
    disabledSteps.set(Step.SELECT_JETPASS, shouldStepBeDisabled);
  }

  return disabledSteps;
};

const GroupAdmissionReducer: Reducer<GroupAdmissionState, Action> = (state, action): GroupAdmissionState => {
  switch (action.type) {
    case ActionType.DEBUG: {
      return { ...state };
    }
    case ActionType.INITIALIZE: {
      const selectedDates = getSelectedDates(action.payload?.selectedDate);
      const preSelectedDate = selectedDates.size > 0 ? true : false;

      return {
        ...state,
        activeStep: action.payload.activeStep ?? 0,
        steps: action.payload.steps,
        selectedMonth: action.payload.selectedMonth,
        entryVariantType: action.payload.entryVariantType,
        selectedDate: action.payload.selectedDate,
        selectedDates: selectedDates,
        preSelectedDate: preSelectedDate,
        variants: action.payload.variants,
        variantsForSelectedDate: action.payload.variantsForSelectedDate,
        selectedDateOpeningHours: action.payload.selectedDateOpeningHours,
        selectedDateProducts: action.payload.selectedDateProducts,
        isCompleted: action.payload.isCompleted ?? new Map<Step, boolean>(),
        isDisabledStep: action.payload.isDisabledStep ?? new Map<Step, boolean>(),
      };
    }
    case ActionType.CHANGE_STEP: {
      return { ...state, activeStep: action.payload.stepIndex };
    }
    case ActionType.CHANGE_QUANTITY: {
      const quantityCopy = new Map(state.quantity);
      quantityCopy.set(action.payload.category, action.payload.quantity);
      /** Reset previous choises and steps */
      const resetState: GroupAdmissionState = {
        ...state,
        isCompleted: new Map<Step, boolean>(),
        selectedVariant: null,
        guests: [],
      };
      return {
        ...resetState,
        quantity: quantityCopy,
        selectedDateOpeningHours: state.preSelectedDate ? state.selectedDateOpeningHours : null,
        selectedDateProducts: state.preSelectedDate ? state.selectedDateProducts : [],
        variantsForSelectedDate: state.preSelectedDate ? state.variantsForSelectedDate : [],
        selectedDate: state.preSelectedDate ? state.selectedDate : null,
        selectedDates: state.preSelectedDate ? state.selectedDates : new Map<string, VisitDate>(),
      };
    }
    case ActionType.COMPLETE_STEP: {
      const completedStep = action.payload.completedStep;

      const disabledSteps = findDisabledSteps(state.isDisabledStep, state.steps, state.guests);

      const isCompletedCopy = new Map(state.isCompleted);
      isCompletedCopy.set(completedStep, true);

      const isAllStepsCompleted = state.steps
        .filter((step) => step.stepType !== Step.SUMMARY)
        .every((step) => isCompletedCopy.get(step.stepType) || disabledSteps.get(step.stepType));
      if (isAllStepsCompleted) {
        isCompletedCopy.set(Step.SUMMARY, true);
      }

      return {
        ...state,
        isCompleted: isCompletedCopy,
        isDisabledStep: disabledSteps,
        activeStep: state.activeStep + 1,
      };
    }
    case ActionType.SELECT_DATE: {
      let modifiedGuests = removeSelectedJetpasses(state.guests);

      const { selectedDate, opens, closing, hideVariant, products } = action.payload;

      const variantsForSelectedDate = GroupAdmissionHelper.getSortedVariantsFromSelection(products, state.variants);

      let selectedDates = new Map<string, VisitDate>();
      let selectedVariant = null;

      if (!hideVariant) {
        if (variantsForSelectedDate.length === 1) {
          selectedVariant = state.variants[variantsForSelectedDate[0]];
          modifiedGuests = getGuestsFromVariantSelection(state.quantity, products, selectedVariant.id);
        }

        if (selectedDateAndVariantHasQuantityForGroup(products, state.selectedVariant, state.quantity)) {
          selectedVariant = state.selectedVariant;
        }

        if (selectedVariant) {
          selectedDates = getSelectedDatesMap(selectedDate, selectedVariant.numberOfDays);
          modifiedGuests = getGuestsFromVariantSelection(state.quantity, products, selectedVariant.id);
        } else {
          selectedDates = getSelectedDates(selectedDate);
        }
      } else {
        modifiedGuests = [];
        selectedDates = getSelectedDatesMap(selectedDate);
      }

      const resetState: GroupAdmissionState = {
        ...state,
        isCompleted: removeIsCompleteForSubsequentSteps(state.activeStep, state.steps, state.isCompleted),
        selectedVariant: selectedVariant,
        guests: modifiedGuests,
      };

      return {
        ...resetState,
        selectedDateOpeningHours: {
          opens: opens ? DateHelper.toStringTimeYYYYMMDDHHMM(opens) : null,
          closing: closing ? DateHelper.toStringTimeYYYYMMDDHHMM(closing) : null,
        },
        selectedDate: selectedDate,
        selectedDates: selectedDates,
        selectedDateProducts: products,
        variantsForSelectedDate: variantsForSelectedDate,
        preSelectedDate: false,
      };
    }

    case ActionType.SELECT_VARIANT: {
      const guests = getGuestsFromVariantSelection(
        state.quantity,
        state.selectedDateProducts,
        action.payload.selectedVariant.id,
      );
      const selectedDate = state.selectedDate;
      const selectedVariant = action.payload.selectedVariant;
      const selectedDates = getSelectedDatesMap(selectedDate, selectedVariant.numberOfDays);

      const resetState: GroupAdmissionState = {
        ...state,
        isCompleted: removeIsCompleteForSubsequentSteps(state.activeStep, state.steps, state.isCompleted),
      };

      return {
        ...resetState,
        selectedVariant: selectedVariant,
        selectedDates: selectedDates,
        guests: guests,
      };
    }

    case ActionType.SELECT_TICKET: {
      const selectedTicketProducts: Array<ProductWithQuantity> = [];

      action.payload.selectedTickets?.forEach((category) => {
        category.productsByVariant.forEach((productsArray) => {
          selectedTicketProducts.push(...productsArray);
        });
      });
      const guests = getGuestsFromTicketSelection(selectedTicketProducts);

      return {
        ...state,
        guests,
        isCompleted: action.payload.hasSubsequentChanges
          ? removeIsCompleteForSubsequentSteps(state.activeStep, state.steps, state.isCompleted)
          : state.isCompleted,
      };
    }

    case ActionType.SELECT_MONTH: {
      return { ...state, selectedMonth: action.payload.selectedMonth };
    }

    case ActionType.SELECT_ENTRY_TIME: {
      const selectedEntryTimes: Array<SelectablePass> = action.payload?.selectedEntryTime ?? [];
      const shouldRemoveSelectedJetpasses: boolean = action.payload?.removeSelectedJetpasses ?? false;

      const updatedSelectedUpsellProducts: Array<UpsellProductsForDate> = action.payload?.updatedSelectedUpsellProducts;
      const updatedGuests: Array<Guest> = shouldRemoveSelectedJetpasses
        ? removeSelectedJetpasses(state.guests)
        : state.guests;
      const selectedDatesCopy: Map<string, VisitDate> = new Map(state.selectedDates);

      selectedEntryTimes.forEach((selectedEntryTime) => {
        const entryTimeDateString = DateHelper.toStringYYYYMMDD(selectedEntryTime.timeSlotFrom);
        const selectedDate = selectedDatesCopy.get(entryTimeDateString);

        if (selectedDate) {
          const updatedSelectedUpsellProductsForDate =
            isNonEmptyArray(updatedSelectedUpsellProducts) &&
            updatedSelectedUpsellProducts.find(
              (upsellProducts) => DateHelper.toStringYYYYMMDD(upsellProducts.date) === entryTimeDateString,
            );

          selectedDate.selectedEntryTime = selectedEntryTime;
          updatedSelectedUpsellProductsForDate
            ? updatedSelectedUpsellProductsForDate.upsellProducts.forEach((upsellProduct) => {
                selectedDate.selectedUpsellProducts.delete(upsellProduct.productId);
              })
            : selectedDate.selectedUpsellProducts;
          selectedDatesCopy.set(entryTimeDateString, selectedDate);
        }
      });

      return {
        ...state,
        guests: updatedGuests,
        selectedDates: selectedDatesCopy,
      };
    }

    case ActionType.ADD_JETPASSES_TO_GUESTS: {
      const guestDTOs: Array<GuestDTO> = action.payload.jetpassGuests;
      const updatedGuests = state.guests.map((guest) => {
        const jetpassGuest = guestDTOs.find((jetpassGuest) => jetpassGuest.id == guest.id);
        jetpassGuest.jetPasses.sort((a, b) => (a.timeSlotFrom < b.timeSlotFrom ? -1 : 0));

        return {
          ...guest,
          name: jetpassGuest ? jetpassGuest.name : null,
          admissionProduct: {
            ...guest.admissionProduct,
            selectedJetpasses: jetpassGuest ? jetpassGuest.jetPasses : [],
          },
        };
      });

      return { ...state, guests: updatedGuests };
    }

    case ActionType.UPDATE_UPSELL_PRODUCT: {
      const upsellProduct: SelectedUpsellProduct = action.payload.upsellProduct;
      const selectedDate: Date = action.payload.selectedDate;
      const updatedQuantity: number = upsellProduct?.quantity ?? 0;
      const productId: number | null = upsellProduct?.productId ?? null;
      const selectedTimeSlot: ITimeSlot | SelectablePass | undefined = upsellProduct?.timeSlot ?? undefined;
      const selectedDatesCopy: Map<string, VisitDate> = new Map(state.selectedDates);

      const selectedDateString = DateHelper.toStringYYYYMMDD(selectedDate);
      const selectedDateFromSelectedDates = selectedDatesCopy.get(selectedDateString);

      if (selectedDateFromSelectedDates) {
        const selectedUpsellProductsCopy: Map<number, SelectedUpsellProduct> = new Map(
          selectedDateFromSelectedDates.selectedUpsellProducts,
        );
        const selectedUpsellProduct: SelectedUpsellProduct = selectedUpsellProductsCopy.get(productId);

        if (selectedUpsellProduct) {
          selectedUpsellProduct.quantity = updatedQuantity;
          selectedUpsellProduct.timeSlot = selectedTimeSlot;
          selectedUpsellProductsCopy.set(productId, selectedUpsellProduct);
        } else {
          selectedUpsellProductsCopy.set(productId, {
            productId: upsellProduct.productId,
            quantity: updatedQuantity,
            timeSlot: selectedTimeSlot,
          });
        }

        selectedDatesCopy.set(selectedDateString, {
          ...selectedDateFromSelectedDates,
          selectedUpsellProducts: selectedUpsellProductsCopy,
        });
      }

      return { ...state, selectedDates: selectedDatesCopy };
    }

    case ActionType.DELETE_UPSELL_PRODUCT: {
      const productId: number = action.payload.productId;
      const selectedDate: Date = action.payload.date;
      const selectedDatesCopy: Map<string, VisitDate> = new Map(state.selectedDates);

      selectedDatesCopy.forEach((visitDate, date) => {
        const selectedUpsellProduct = visitDate.selectedUpsellProducts.get(productId);
        if (selectedUpsellProduct && DateHelper.toStringYYYYMMDD(selectedDate) === date) {
          visitDate.selectedUpsellProducts.delete(productId);
        }
      });

      return { ...state, selectedDates: selectedDatesCopy };
    }

    case ActionType.SELECT_MANDATORY_JETPASS: {
      const entrance = action.payload.entrance;
      const timeSlot = action.payload.timeSlot;

      const mandatoryPass: SelectablePass = {
        productId: entrance.productId,
        attractionId: entrance.attractionId,
        attractionName: entrance.attractionName,
        timeSlotFrom: timeSlot.timeSlotFrom,
        timeSlotTo: timeSlot.timeSlotTo,
        timeSlotId: timeSlot.timeSlotId,
        quantity: timeSlot.quantity,
      };

      const updatedGuests = state.guests.map((guest) => {
        return {
          ...guest,
          admissionProduct: {
            ...guest.admissionProduct,
            selectedMandatoryJetpass: { ...mandatoryPass },
          },
        };
      });

      return {
        ...state,
        guests: updatedGuests,
      };
    }
    default: {
      return { ...state };
    }
  }
};

export { GroupAdmissionReducer, GroupAdmissionInitialState };
