// @ts-strict-ignore
import { useMemo, useState } from "react";
import styles from "./group-size.module.less";
import QuantitySelectorStyled from "@/core/components/primitives/quantity-selector-styled/quantity-selector-styled";
import {
  ActionType,
  BannerData,
  Dispatchable,
  GroupAdmissionState,
  Step,
} from "@/core/types/state/group-admission/group-admission-types";
import DialogModal from "@/core/components/primitives/dialog-modal/dialog-modal";
import { AnimatePresence } from "framer-motion";
import { EntryVariant, VisitorCategory } from "@/core/types/services/purchase-flow-service-types";
import PromotionBanner from "./promotion-banner/promotion-banner";
import { sum } from "lodash-es";
import { GroupAdmissionHelper } from "@/core/helpers";
import StepBackdrop from "../../components/step-backdrop";
import { useTranslation } from "react-i18next";
import useFocus from "@/core/hooks/use-focus";
import { useStepWarning } from "../../step-warning/step-warning";
import { ButtonRow } from "../../components/button-row";
import { LabelKey } from "@/core/labels/i18n";

type GroupSizeProps = {
  quantity: GroupAdmissionState["quantity"] | null;
  visitorCategories: Map<VisitorCategory["id"], VisitorCategory>;
  selectedVariant: EntryVariant;
  ignoreVariantSelection: boolean;
  isNextStepCompleted: boolean;
  bannerProps: BannerData | undefined;
  minMaxEntryProducts: { minEntryProducts: number; maxEntryProducts: number };
  stepWrapperRef: HTMLElement;
} & Dispatchable;

const isCategoryIndependent = (
  category: VisitorCategory["id"],
  visitorCategories: Map<VisitorCategory["id"], VisitorCategory>,
) => {
  const categoryObject = visitorCategories.get(category);
  return categoryObject ? !categoryObject.notSoldSeparately : false;
};

const isStepCompleted = (
  quantity: GroupAdmissionState["quantity"],
  visitorCategories: Map<VisitorCategory["id"], VisitorCategory>,
) => {
  for (const [category, quantityValue] of quantity) {
    if (quantityValue > 0 && isCategoryIndependent(category, visitorCategories)) {
      return true;
    }
  }

  return false;
};

type WarningTexts = {
  title: LabelKey;
  bodyText: LabelKey;
};

const getWarningTexts = (
  quantity: GroupAdmissionState["quantity"],
  visitorCategories: Map<VisitorCategory["id"], VisitorCategory>,
  minGroupSizeFullfilled: boolean,
): WarningTexts => {
  const selectedCategories = [...(quantity?.entries() ?? [])].filter(([, value]) => value > 0);

  const isCategoryNotIndependent =
    selectedCategories.length > 0 &&
    selectedCategories.every(([category]) => {
      return !isCategoryIndependent(category, visitorCategories);
    });

  if (isCategoryNotIndependent && minGroupSizeFullfilled) {
    return {
      title: "groupSizeStepWarningNotIndependentTitle",
      bodyText: "groupSizeStepWarningNotIndependentBodyText",
    };
  }
  return {
    title: "groupSizeStepWarningNotEnoughVisitorsSelectedTitle",
    bodyText: "groupSizeStepWarningNotEnoughVisitorsSelectedBodyText",
  };
};

function GroupSize({
  quantity,
  visitorCategories,
  selectedVariant,
  isNextStepCompleted,
  ignoreVariantSelection,
  bannerProps,
  minMaxEntryProducts,
  stepWrapperRef,
  dispatch,
}: GroupSizeProps) {
  const [informationModalProps, setInformationModalProps] = useState(null);
  const totalGroupSize = useMemo(() => sum([...quantity.values()]), [quantity]);
  const [showStepWarning, setShowStepWarning] = useState(false);
  const minGroupSizeFullfilled = totalGroupSize >= minMaxEntryProducts.minEntryProducts;
  const maxGroupSizeReached = totalGroupSize === minMaxEntryProducts.maxEntryProducts;
  const [focusRef, setFocus] = useFocus<HTMLDivElement>();
  const [warningTexts, setWarningTexts] = useState<WarningTexts>();

  const { scrollAndFocusOnWarning, StepWarning } = useStepWarning({
    title: warningTexts?.title,
    bodyText: warningTexts?.bodyText,
  });

  const { t } = useTranslation();

  const onChangeQuantity = (category: VisitorCategory["id"], newQuantity: number, overrideClick?: boolean) => {
    if (isNextStepCompleted && !overrideClick && (selectedVariant !== null || ignoreVariantSelection)) {
      setInformationModalProps({ category: category, quantity, newQuantity });
    } else {
      dispatch({ type: ActionType.CHANGE_QUANTITY, payload: { category: category, quantity: newQuantity } });
      if (overrideClick) {
        setFocus();
      }
      setInformationModalProps(null);
    }
  };

  const onClickNextStep = () => {
    if (!isStepCompleted(quantity, visitorCategories) || !minGroupSizeFullfilled) {
      setWarningTexts(getWarningTexts(quantity, visitorCategories, minGroupSizeFullfilled));
      setShowStepWarning(true);
      scrollAndFocusOnWarning();
    } else {
      setShowStepWarning(false);
      GroupAdmissionHelper.scrollAndCompleteStep(stepWrapperRef, Step.GROUP_SIZE, dispatch, true);
    }
  };

  function closeDialog() {
    setFocus();
    setInformationModalProps(null);
  }

  return (
    <div className={styles.wrapper} ref={focusRef} tabIndex={-1}>
      <AnimatePresence mode="wait">{showStepWarning && <StepWarning />}</AnimatePresence>
      <StepBackdrop>
        <div className={styles.categories}>
          {[...visitorCategories.values()].map((category) => {
            const quantityForCategory = quantity.get(category.id) ? quantity.get(category.id) : 0;
            return (
              <div key={category.id} className={styles.category}>
                <QuantitySelectorStyled
                  quantity={quantityForCategory}
                  minQuantity={category.minCount ?? 0}
                  maxQuantity={maxGroupSizeReached ? quantityForCategory : category.maxCount}
                  label={category.name}
                  sublabel={category.description}
                  onQuantityChange={(newQuantity) => onChangeQuantity(category.id, newQuantity)}
                />
              </div>
            );
          })}
        </div>
      </StepBackdrop>

      {bannerProps && bannerProps.bannerText && <PromotionBanner {...bannerProps} />}

      <ButtonRow onClickStepComplete={onClickNextStep} nextTestId="group-size-next-button" />

      <AnimatePresence>
        {informationModalProps && (
          <DialogModal
            headingText={t("groupSizeStepDialogHeading")}
            bodyText={t("groupSizeStepDialogBodyText")}
            primaryButtonText={t("groupSizeStepDialogConfirmChange")}
            primaryButtonAction={() =>
              onChangeQuantity(informationModalProps.category, informationModalProps.newQuantity, true)
            }
            secondaryButtonText={t("cancel")}
            secondaryButtonAction={closeDialog}
            onCloseFunction={closeDialog}
            contentfulLabelIds={{
              headingText: "groupSizeStepDialogHeading",
              bodyText: "groupSizeStepDialogBodyText",
              confirmChange: "groupSizeStepDialogConfirmChange",
              cancelChange: "cancel",
            }}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

export default GroupSize;
