import { DependencyList, useEffect } from "react";

/**
 * This hook listens for the `pageshow` event and triggers the provided event listener
 * if the page was loaded from the bfcache (back-forward cache). This happens when the
 * user navigates back to a page and it was cached in the bfcache, which will not cause
 * a full page reload or a navigation event in Reach Router. This hook is useful for
 * cases where the user has followed a link to an external page or when they have been
 * redirected programmatically outside Reach Router, for example by the Klarna checkout.
 *
 * @see https://web.dev/bfcache/
 * @see https://developer.mozilla.org/en-US/docs/Web/API/Window/pageshow_event
 */
export const useBackFromBfcache = (eventListener: (event: PageTransitionEvent) => void, deps?: DependencyList) => {
  useEffect(() => {
    const listener = (event: PageTransitionEvent) => {
      if (event.persisted) {
        eventListener(event);
      }
    };
    window.addEventListener("pageshow", listener);
    return () => window.removeEventListener("pageshow", listener);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
};
