// @ts-strict-ignore
import { useState } from "react";
import styles from "./mandatory-jetpass-card.module.less";
import { motion } from "framer-motion";
import { SecondaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { IGLKMyParksEntranceWithProductId, IGLKMyParksTimeSlot } from "@/core/types/time-slots";
import { useTranslation } from "react-i18next";
import Icon from "@/core/components/primitives/icon/icon";

type MandatoryJetpassCardProps = {
  entrance: IGLKMyParksEntranceWithProductId;
  timeSlot: IGLKMyParksTimeSlot;
  title: string;
  imageUrl?: string;
  shortDescriptionInList?: string;
  preamble?: { preamble?: string };
  onClickButton?: (entrance: IGLKMyParksEntranceWithProductId, timeSlot: IGLKMyParksTimeSlot) => void;
  isSelected: boolean;
  isSoldOut: boolean;
  buttonLabel: string;
};

const MandatoryJetpassCard = ({
  title,
  imageUrl,
  shortDescriptionInList,
  entrance,
  preamble,
  buttonLabel,
  onClickButton,
  isSelected,
  isSoldOut,
  timeSlot,
}: MandatoryJetpassCardProps) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const { t } = useTranslation();

  return (
    <div className={styles.wrapper}>
      <div className={`${styles.selectedOutline} ${isSelected ? styles.selected : ""}`}></div>
      <div className={styles.border}>
        <div className={styles.innerWrapper}>
          <div className={styles.topWrapper}>
            <div className={styles.imageContainer}>
              {imageUrl && (
                <img loading="lazy" src={`${imageUrl}?fm=webp&w=600&q=90`} alt={title} className={styles.image} />
              )}
            </div>

            <div className={styles.textWrapper}>
              <h3 className="heading-xs">{title}</h3>
              {shortDescriptionInList && <p>{shortDescriptionInList}</p>}
              <SecondaryButton
                className={styles.selectButton}
                isFullWidth={true}
                isDisabled={isSoldOut}
                label={buttonLabel}
                onClick={() => onClickButton(entrance, timeSlot)}
              />
            </div>
          </div>
          <div className={styles.detailsWrapper}>
            {preamble && (
              <button className={`${styles.expandButton}`} onClick={() => setIsExpanded(!isExpanded)}>
                <motion.span
                  initial={{ rotate: isExpanded ? 180 : 0 }}
                  animate={{ rotate: isExpanded ? 180 : 0 }}
                  className={styles.iconWrapper}
                >
                  <Icon name="expand-more" className={styles.icon} />
                </motion.span>
                <span
                  className={styles.expandButtonLabel}
                  data-contentful-label-id={isExpanded ? "hideDetails" : "showDetails"}
                >
                  {isExpanded ? t("hideDetails") : t("showDetails")}
                </span>
              </button>
            )}
            {preamble && (
              <motion.div
                className={styles.expandWrapper}
                initial={{ height: isExpanded ? 0 : "auto" }}
                animate={{ height: isExpanded ? "auto" : 0 }}
                transition={{ duration: 0.2, type: "tween" }}
              >
                <div className={styles.expandInnerWrapper}>
                  <p>{preamble.preamble}</p>
                </div>
              </motion.div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default MandatoryJetpassCard;
