import styles from "./area-loader.module.less";
import CalendarLoader from "@/core/components/modules/calendar-loader/calendar-loader";
import { motion } from "framer-motion";

type AreaLoaderProps = {
  loaderText: string;
  key?: string;
  contentfulLabelId?: string;
  loaderTextClassName?: string;
};

const AreaLoader = ({ loaderText, key, contentfulLabelId, loaderTextClassName }: AreaLoaderProps) => {
  return (
    <motion.div
      key={key ? key : "area-loader"}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{ type: "tween", ease: "easeOut" }}
      className={styles.wrapper}
    >
      <CalendarLoader
        loaderText={loaderText}
        contentfulLabelId={contentfulLabelId}
        loaderTextClassName={loaderTextClassName}
      />
    </motion.div>
  );
};

export default AreaLoader;
