// @ts-strict-ignore
import styles from "./step-wrapper.module.less";
import { Variants, motion } from "framer-motion";
import { Action, ActionType, Step } from "@/core/types/state/group-admission/group-admission-types";
import { exhaustiveCheck, isNonEmptyArray } from "@/core/helpers";
import { multipleClassNames } from "@/core/helpers/string-helper";
import { Dispatch, MutableRefObject, PropsWithChildren, ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { GhostButton } from "@/core/components/primitives/parks-button/parks-button";
import Icon from "@/core/components/primitives/icon/icon";
import { LabelKey } from "@/core/labels/i18n";
import { OpeningHoursItem } from "@parksandresorts/webapiproxy-types";

type StepWrapperProps = {
  stepRefArray: MutableRefObject<Array<HTMLElement>>;
  isCompleted: boolean;
  isActive: boolean;
  stepIndex: number;
  titleLabelId: LabelKey;
  stepType: Step;
  stepSummary?: ReactNode;
  selectedDateOpeningHours?: Pick<OpeningHoursItem, "opens" | "closing">;
  showOpeningHoursInFixedDateSummary?: boolean;
  isDisabledStep?: boolean;
  useFixedDateStep?: boolean;
  dispatch: Dispatch<Action>;
};

function getStepType(stepType: Step) {
  switch (stepType) {
    case Step.FIXED_DATE:
      return "FixedDate";
    case Step.GROUP_SIZE:
      return "GroupSize";
    case Step.SELECT_DATE:
      return "SelectDate";
    case Step.SELECT_ENTRY_TIME:
      return "SelectEntryTime";
    case Step.SELECT_MANDATORY_JETPASS:
      return "SelectMandatoryJetpass";
    case Step.SELECT_TICKET:
      return "SelectTicket";
    case Step.UPSELL:
      return "Upsell";
    case Step.SELECT_JETPASS:
      return "SelectJetpass";
    case Step.SUMMARY:
      return "Summary";
    default:
      return exhaustiveCheck(stepType);
  }
}

const StepWrapper = ({
  stepRefArray,
  isActive,
  isCompleted,
  stepIndex,
  titleLabelId,
  stepType,
  stepSummary,
  isDisabledStep,
  useFixedDateStep = false,
  dispatch,
  children,
}: PropsWithChildren<StepWrapperProps>) => {
  const { t } = useTranslation();

  const isUpcomingStep = !isActive && !isCompleted;
  const isPreviousStep = !isActive && !isUpcomingStep;
  const isLastStep =
    stepRefArray && isNonEmptyArray(stepRefArray.current) && stepIndex === stepRefArray.current.length - 1;

  const summaryAnimationProps = {
    initial: {
      opacity: isUpcomingStep || isActive ? 0 : 0.7,
      height: isUpcomingStep || isActive ? 0 : "auto",
    },
    animate: {
      opacity: isPreviousStep || isDisabledStep ? 0.7 : 0,
      height: isPreviousStep || isDisabledStep ? "auto" : 0,
    },
    transition: { opacity: { duration: 0.15 } },
  };

  const stepContentAnimate: Variants = {
    isActive: {
      display: "block",
      height: "auto",
      opacity: 1,
      transition: {
        opacity: { delay: 0.2, duration: 0.3 },
        height: { duration: 0.4, type: "tween" },
      },
    },
    notActive: {
      height: 0,
      opacity: 0,
      transition: {
        opacity: { duration: 0.2 },
        height: { duration: 0.4, type: "tween" },
      },
      transitionEnd: {
        display: "none",
      },
    },
  };

  const isUpsellStep = getStepType(stepType) === "Upsell";
  const visualStepIndex = useFixedDateStep ? stepIndex : stepIndex + 1; // When using Fixed Date Step, make first step after Fixed Date Step look like first step

  // We concatenate these strings instead of using two spans for two reasons:
  // 1. Screen readers will read the full step text as one element, improving accessibility.
  // 2. Chrome's automatic translation works better with single text nodes. (or multiple spans, but see point 1)
  const fullStepTitle = !isCompleted || isActive ? `${visualStepIndex}. ${t(titleLabelId)}` : t(titleLabelId);

  return (
    <div
      ref={(ref) => {
        stepRefArray.current[stepIndex] = ref;
      }}
      className={multipleClassNames(
        styles.wrapper,
        isDisabledStep && styles.disabledStep,
        isUpsellStep && styles.noSidePadding,
      )}
    >
      {isActive && stepIndex > 0 && <span className={styles.topBorder} />}
      <div
        className={multipleClassNames(
          styles.header,
          isUpsellStep && styles.addSidePadding,
          isCompleted && !isActive && styles.completed,
          isActive && styles.active,
          isUpcomingStep && styles.isUpcomingStep,
        )}
      >
        {isCompleted && !isActive && (
          <div className={styles.completedIcon} data-testid={`${stepType}-step-completed`}>
            <Icon name="done" />
          </div>
        )}

        <div className={styles.headerTextWrapper}>
          <h2
            className={multipleClassNames(isActive ? "heading-xs" : "body-s", styles.headerTitle)}
            data-contentful-label-id={titleLabelId}
          >
            {fullStepTitle}
          </h2>
          {stepSummary && <motion.div {...summaryAnimationProps}>{stepSummary}</motion.div>}
          {isDisabledStep && (
            <motion.p {...summaryAnimationProps} className={multipleClassNames(styles.summary, "p_small")}>
              {t(`stepWrapper${getStepType(stepType)}DisabledText`)}
            </motion.p>
          )}
        </div>
        {isCompleted && !isActive && !isDisabledStep && (
          <GhostButton
            onClick={() => dispatch({ type: ActionType.CHANGE_STEP, payload: { stepIndex: stepIndex } })}
            className={styles.changeButton}
            contentfulLabelId={stepType === Step.SUMMARY ? "stepWrapperGoTo" : "modify"}
            label={stepType === Step.SUMMARY ? t("stepWrapperGoTo") : t("modify")}
          />
        )}
      </div>
      <motion.div
        initial={{
          height: isActive ? "auto" : 0,
          opacity: isActive ? 1 : 0,
          display: isActive ? "block" : "none",
        }}
        animate={isActive ? "isActive" : "notActive"}
        variants={stepContentAnimate}
        className={styles.contentWrapper}
      >
        {children}
      </motion.div>
      {isActive && !isLastStep && <span className={styles.bottomBorder} />}
    </div>
  );
};

export default StepWrapper;
