import { motion } from "framer-motion";
import styles from "./calendar-loader.module.less";
import SiteInfoHelper, { ICalendarLoaderIcons } from "@/core/helpers/site-info-helper";

type Props = {
  loaderText: string;
  loaderIconsOverride?: ICalendarLoaderIcons;
  wrapperClassName?: string;
  loaderTextClassName?: string;
  contentfulLabelId?: string;
};

const CalendarLoader = ({
  loaderText,
  loaderIconsOverride,
  wrapperClassName,
  loaderTextClassName,
  contentfulLabelId,
}: Props) => {
  const loadingContainerVariants = {
    start: {
      transition: {
        staggerChildren: 0.2,
      },
    },
  };

  const iconAnimationVariants = {
    initial: {
      y: "0%",
    },
    start: {
      y: ["0%", "-7.5%", "0%"],
      transition: {
        duration: 0.6,
        ease: "easeInOut",
        times: [0, 0.5, 1],
        repeat: Infinity,
        repeatType: "loop" as const,
        repeatDelay: 0.8,
      },
    },
  };

  const { firstImage, secondImage, thirdImage }: Partial<ICalendarLoaderIcons> = loaderIconsOverride
    ? loaderIconsOverride
    : SiteInfoHelper.getCalendarLoaderIcons() ?? {};

  return (
    <div className={`${styles.loaderWrapper} ${wrapperClassName ? wrapperClassName : ""}`}>
      {loaderText && (
        <motion.div
          className={`${styles.loaderText} ${loaderTextClassName ? loaderTextClassName : ""}`}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5, ease: "easeIn" }}
        >
          <h2 data-contentful-label-id={contentfulLabelId}>{loaderText}</h2>
          <motion.ul
            className={styles.animalList}
            variants={loadingContainerVariants}
            initial="initial"
            animate="start"
          >
            <motion.li variants={iconAnimationVariants}>
              {firstImage && <img src={firstImage} alt="loader icon" />}
            </motion.li>
            <motion.li variants={iconAnimationVariants}>
              {secondImage && <img src={secondImage} alt="loader icon" />}
            </motion.li>
            <motion.li variants={iconAnimationVariants}>
              {thirdImage && <img src={thirdImage} alt="loader icon" />}
            </motion.li>
          </motion.ul>
        </motion.div>
      )}
    </div>
  );
};

export default CalendarLoader;
