import { useMemo } from "react";
import { useDeliveryItemsFromCart } from "@/core/hooks/use-delivery-items-from-cart";
import styles from "./summary.module.less";
import {
  isNonEmptyArray,
  DateHelper,
  insertIntoString,
  CurrencyHelper,
  cartItemToItemInCart,
  isShippingFeeProduct,
  usedVoucherCodesSummaryItems,
  isTruthy,
  multipleClassNames,
} from "@/core/helpers";
import { Guest, VisitDate, PurchaseFlowDate } from "@/core/types/state/group-admission/group-admission-types";
import { sum } from "lodash-es";
import SummaryList, { Summary as CategorySummary } from "@/core/components/primitives/summary-list/summary-list";
import { useTranslation } from "react-i18next";
import { Translation } from "@/core/labels/i18n";
import { SummaryTotal } from "@/core/components/primitives/summary-total/summary-total";
import { useCartHandlerForPurchaseflow } from "./use-cart-handler-for-purchaseflow";
import { useShopServiceCartContext } from "@/core/contexts";
import { ShopServicePayment } from "@/core/components/modules/shop-service-payment/shop-service-payment";
import { CheckoutError } from "@/core/components/primitives/shop-service-status/shop-service-status";
import { ItemInCart } from "@/core/components/modules/cart/cart-item";
import Cart from "@/core/components/modules/cart/cart";
import { useCartItemsFromCartResponse, useProducts, useRemoveVoucherFromCart } from "@/core/hooks";
import { SkeletonRectangle } from "@/core/components/primitives/skeleton-rectangle/skeleton-rectangle";
import { UsedVoucherCode } from "@/core/components/primitives/used-voucher-code/used-voucher-code";

type SummaryProps = {
  selectedDates: Map<string, [VisitDate, PurchaseFlowDate]>;
  guests: Array<Guest>;
  isActive: boolean;
};

type PurchaseFlowCategorySummary = Omit<CategorySummary, "summaryItems"> &
  (
    | {
        state: "ready";
        itemInCarts: Array<ItemInCart>;
      }
    | { state: "loading"; skeletonAmounts: number }
  );

export const getIntroText = (visitDatesArray: Array<VisitDate>, t: Translation): string => {
  const dates = visitDatesArray.map((visitDate) => DateHelper.toStringMMDDWeekday(visitDate.date)).join(" & ");
  return insertIntoString(t("summaryStepIntroText"), dates);
};

const Summary = ({ guests, selectedDates, isActive }: SummaryProps) => {
  const { t } = useTranslation();

  const visitDatesArray = useMemo(() => (selectedDates.size > 0 ? [...selectedDates.values()] : []), [selectedDates]);

  const { data: cart, cartId, error: cartError, removeCartItem, updateCartItemQuantity } = useShopServiceCartContext();
  const {
    cartItems: purchaseFlowCartItems,
    cartReadyForPayment,
    error,
  } = useCartHandlerForPurchaseflow(guests, visitDatesArray, isActive);

  const productIdsOfAdmissionProducts = useMemo(() => guests.map((guest) => guest.admissionProduct.id), [guests]);

  const productIdsOfUpsellProducts = useMemo(
    () => visitDatesArray.flatMap(([visitDate]) => [...visitDate.selectedUpsellProducts.keys()]),
    [visitDatesArray],
  );

  const allUniqueProductIds = useMemo(() => {
    return new Set<number>([...productIdsOfAdmissionProducts, ...productIdsOfUpsellProducts]);
  }, [productIdsOfAdmissionProducts, productIdsOfUpsellProducts]);

  const { productsById } = useProducts(Array.from(allUniqueProductIds));

  const existingItemsInCart = useMemo(() => {
    return cart?.cartItems.filter(
      (item) => !purchaseFlowCartItems.some((flowItem) => flowItem.cartItemGuid === item.cartItemGuid),
    );
  }, [cart?.cartItems, purchaseFlowCartItems]);

  const cartItemsOfExistingItemsInCart = useCartItemsFromCartResponse(existingItemsInCart, cart);

  const usedVouchers = usedVoucherCodesSummaryItems(cart?.voucherCodes ?? [], cart?.redeemableValidationResults ?? []);

  const { mutate: removeVoucherCode, isPending: removeVoucherCodePending } = useRemoveVoucherFromCart(
    cart?.cartGuid ?? "",
  );

  const allCartItems = useCartItemsFromCartResponse(cart?.cartItems, cart) ?? [];
  const deliveryRows = useDeliveryItemsFromCart(allCartItems, productsById);

  const entryTicketSummary = useMemo((): PurchaseFlowCategorySummary => {
    if (purchaseFlowCartItems.length === 0 || !cartReadyForPayment) {
      return {
        state: "loading",
        category: t("summaryStepEntryTickets"),
        quantity: t("summaryStepPieces", { count: productIdsOfAdmissionProducts.length }),
        sumPrice: "",
        skeletonAmounts: productIdsOfAdmissionProducts.length,
      };
    }
    const entryTicketsInPurchaseFlowCartItems = purchaseFlowCartItems
      .filter((item) => productIdsOfAdmissionProducts.includes(item.productId))
      .map((item) => cart?.cartItems.find((cartItem) => cartItem.cartItemGuid === item.cartItemGuid))
      .filter(isTruthy);

    const itemInCarts = entryTicketsInPurchaseFlowCartItems.map((item) =>
      cartItemToItemInCart(item, productsById, cart?.discountItems ?? [], cart?.redeemableValidationResults ?? [], t),
    );

    const priceSum = sum(itemInCarts.map((item) => item.price));

    return {
      state: "ready",
      category: t("summaryStepEntryTickets"),
      quantity: t("summaryStepPieces", { count: sum(itemInCarts.map((item) => item.quantity)) }),
      sumPrice: CurrencyHelper.formatToSekWithPossiblePrecision(priceSum),
      itemInCarts,
    };
  }, [
    purchaseFlowCartItems,
    cartReadyForPayment,
    t,
    productIdsOfAdmissionProducts,
    productsById,
    cart?.discountItems,
    cart?.redeemableValidationResults,
    cart?.cartItems,
  ]);

  const upsellProductsSummary = useMemo((): PurchaseFlowCategorySummary => {
    if (purchaseFlowCartItems.length === 0 || !cartReadyForPayment) {
      return {
        state: "loading",
        category: t("summaryStepAddOns"),
        quantity: t("summaryStepPieces", { count: productIdsOfUpsellProducts.length }),
        sumPrice: "",
        skeletonAmounts: productIdsOfUpsellProducts.length,
      };
    }

    const upsellProductsInPurchaseFlowCartItems = purchaseFlowCartItems
      .filter((item) => productIdsOfUpsellProducts.includes(item.productId))
      .map((item) => cart?.cartItems.find((cartItem) => cartItem.cartItemGuid === item.cartItemGuid))
      .filter(isTruthy);

    const itemInCarts = upsellProductsInPurchaseFlowCartItems.map((item) =>
      cartItemToItemInCart(item, productsById, cart?.discountItems ?? [], cart?.redeemableValidationResults ?? [], t),
    );

    const priceSum = sum(itemInCarts.map((item) => item.price));

    return {
      state: "ready",
      category: t("summaryStepAddOns"),
      quantity: t("summaryStepPieces", { count: sum(itemInCarts.map((item) => item.quantity)) }),
      sumPrice: CurrencyHelper.formatToSekWithPossiblePrecision(priceSum),
      itemInCarts,
    };
  }, [
    purchaseFlowCartItems,
    cartReadyForPayment,
    t,
    productIdsOfUpsellProducts,
    productsById,
    cart?.discountItems,
    cart?.redeemableValidationResults,
    cart?.cartItems,
  ]);

  const introText = getIntroText(
    visitDatesArray.map(([visitDate]) => visitDate),
    t,
  );

  return (
    <section className={styles.wrapper}>
      <p data-contentful-label-id="summaryStepIntroText">{introText}</p>
      <div>
        <SummaryList
          category={entryTicketSummary.category}
          quantity={entryTicketSummary.quantity}
          sumPrice={entryTicketSummary.sumPrice}
          preExpanded={true}
          removeChildrenWhenUnexpanded
          ariaLabelsIcon={{
            whenExpanded: t("summaryStepEntryTicketsIconExpanded"),
            whenCollapsed: t("summaryStepEntryTicketsIconCollapsed"),
          }}
        >
          {entryTicketSummary.state === "loading" &&
            Array.from({ length: entryTicketSummary.skeletonAmounts }).map((_, idx) => (
              <SkeletonRectangle className={styles.cartItemSkeleton} key={idx} />
            ))}
          {entryTicketSummary.state === "ready" && (
            <Cart
              hideContinueShopping
              hideGoToCheckout
              hideHeadline
              hideTotalSum
              hideShippingProducts
              checkoutUrl={undefined}
              isDisabled={false}
              totalSumInclVat={0} //Will not be used
              products={entryTicketSummary.itemInCarts}
              innerWrapperClassName={styles.cartInnerWrapper}
            />
          )}
        </SummaryList>
        {((upsellProductsSummary.state === "loading" && upsellProductsSummary.skeletonAmounts > 0) ||
          (upsellProductsSummary.state === "ready" && isNonEmptyArray(upsellProductsSummary.itemInCarts))) && (
          <SummaryList
            category={upsellProductsSummary.category}
            quantity={upsellProductsSummary.quantity}
            sumPrice={upsellProductsSummary.sumPrice}
            removeChildrenWhenUnexpanded
            ariaLabelsIcon={{
              whenExpanded: t("summaryStepAddOnsIconExpanded"),
              whenCollapsed: t("summaryStepAddOnsIconCollapsed"),
            }}
          >
            {upsellProductsSummary.state === "loading" &&
              Array.from({ length: upsellProductsSummary.skeletonAmounts }).map((_, idx) => (
                <SkeletonRectangle className={styles.cartItemSkeleton} key={idx} />
              ))}
            {upsellProductsSummary.state === "ready" && (
              <Cart
                hideContinueShopping
                hideGoToCheckout
                hideHeadline
                hideTotalSum
                hideShippingProducts
                checkoutUrl={undefined}
                isDisabled={false}
                totalSumInclVat={0} //Will not be used
                products={upsellProductsSummary.itemInCarts}
                innerWrapperClassName={styles.cartInnerWrapper}
              />
            )}
          </SummaryList>
        )}
        {isNonEmptyArray(cartItemsOfExistingItemsInCart) && (
          <SummaryList
            category={t("summaryStepExistingItems")}
            quantity={t("summaryStepPieces", {
              count: sum(
                cartItemsOfExistingItemsInCart
                  .filter((item) => !isShippingFeeProduct(productsById.get(item.productId ?? 0)))
                  .map((item) => item.quantity),
              ),
            })}
            sumPrice={CurrencyHelper.formatToSekWithPossiblePrecision(
              sum(cartItemsOfExistingItemsInCart.map((item) => item.price)),
            )}
            removeChildrenWhenUnexpanded
            ariaLabelsIcon={{
              whenExpanded: t("summaryStepExistingItemsIconExpanded"),
              whenCollapsed: t("summaryStepExistingItemsIconCollapsed"),
            }}
          >
            <Cart
              hideContinueShopping
              hideGoToCheckout
              hideHeadline
              hideTotalSum
              hideShippingProducts
              checkoutUrl={undefined}
              isDisabled={false}
              totalSumInclVat={0} //Will not be used
              products={cartItemsOfExistingItemsInCart}
              innerWrapperClassName={styles.cartInnerWrapper}
              deleteCartItem={(item) => removeCartItem(item.id)}
              updateCartItemQuantity={(item, quantity) => updateCartItemQuantity(item.id, quantity)}
            />
          </SummaryList>
        )}

        {isNonEmptyArray(deliveryRows) && (
          <SummaryList
            preExpanded
            category={t("delivery")}
            quantity=""
            removeChildrenWhenUnexpanded
            ariaLabelsIcon={{
              whenExpanded: t("deliveryIconExpanded"),
              whenCollapsed: t("deliveryIconCollapsed"),
            }}
          >
            <Cart
              hideContinueShopping
              hideGoToCheckout
              hideHeadline
              hideTotalSum
              checkoutUrl={undefined}
              isDisabled
              totalSumInclVat={0}
              products={deliveryRows}
              innerWrapperClassName={multipleClassNames(styles.cartInnerWrapper, styles.deliveryCartInnerWrapper)}
            />
          </SummaryList>
        )}

        {isNonEmptyArray(usedVouchers) && (
          <SummaryList
            preExpanded
            category={t("usedVoucherCodes")}
            quantity={t("summaryStepPieces", { count: usedVouchers.length })}
            ariaLabelsIcon={{
              whenExpanded: t("usedVoucherCodesIconExpanded"),
              whenCollapsed: t("usedVoucherCodesIconCollapsed"),
            }}
          >
            {usedVouchers.map((voucher, index) => (
              <UsedVoucherCode
                key={index}
                code={voucher.code}
                variant={voucher.variant}
                disabled={removeVoucherCodePending}
                onDelete={() => {
                  removeVoucherCode(voucher.code);
                }}
                description={voucher.description}
              />
            ))}
          </SummaryList>
        )}
        {cart && cartReadyForPayment ? (
          <SummaryTotal
            type="price"
            labelId="total"
            price={cart.cartPrice.amount.amountIncludingVat}
            originalProductSummaryAmount={cart.cartPrice.amountBeforeDiscounts?.amountIncludingVat}
          />
        ) : (
          <SkeletonRectangle className={styles.summaryTotalSkeleton} />
        )}
      </div>
      {error || cartError ? <CheckoutError /> : <ShopServicePayment cartId={cartId} enabled={cartReadyForPayment} />}
    </section>
  );
};

export default Summary;
