// @ts-strict-ignore
import { DateHelper, GroupAdmissionHelper, isNonEmptyArray } from "@/core/helpers";
import { useIsMountedRef } from "@/core/hooks/use-get-is-mounted";
import { useState, useEffect } from "react";
import { TimeSlotService } from "@/core/services";
import { RideStore } from "@/core/stores";
import {
  ActionType,
  GroupAdmissionState,
  Guest,
  Step,
  StepProps,
} from "@/core/types/state/group-admission/group-admission-types";
import styles from "./select-mandatory-jetpass.module.less";
import MandatoryJetpassCard from "./mandatory-jetpass-card/mandatory-jetpass-card";
import { IGLKMyParksEntranceWithProductId, IGLKMyParksTimeSlot } from "@/core/types/time-slots";
import { RideBlock } from "@/core/types/ride/ride";
import { useTranslation } from "react-i18next";
import { ButtonRow } from "../../components/button-row";

type SelectMandatoryJetpassProps = {
  selectedDate: Date;
  guests: Array<Guest>;
  quantity: GroupAdmissionState["quantity"];
  stepWrapperRef: HTMLElement;
} & StepProps;

const SelectMandatoryJetpass = ({
  selectedDate,
  guests,
  dispatch,
  stepIndex,
  onClickBack,
  stepWrapperRef,
}: SelectMandatoryJetpassProps) => {
  const isMountedRef = useIsMountedRef();
  const [rides, setRides] = useState<Map<number, RideBlock>>(new Map<number, RideBlock>());
  const [ridesForSelectedDate, setRidesForSelectedDate] = useState<Array<IGLKMyParksEntranceWithProductId>>([]);
  const { t } = useTranslation();

  const onClickMandatoryJetpass = (entrance: IGLKMyParksEntranceWithProductId, timeSlot: IGLKMyParksTimeSlot) => {
    dispatch({ type: ActionType.SELECT_MANDATORY_JETPASS, payload: { entrance: entrance, timeSlot: timeSlot } });
  };

  const onClickStepComplete = () => {
    GroupAdmissionHelper.scrollAndCompleteStep(stepWrapperRef, Step.SELECT_MANDATORY_JETPASS, dispatch);
  };

  const [firstGuest] = guests;
  const hasSelectedMandatoryJetpass = (firstGuest && firstGuest?.admissionProduct?.selectedMandatoryJetpass) || false;

  useEffect(() => {
    if (!isNonEmptyArray(guests) || !selectedDate) {
      return;
    }

    TimeSlotService.getEntrancesAndJetpassTimeslots(
      firstGuest.admissionProduct.id,
      DateHelper.toStringYYYYMMDD(selectedDate),
    )
      .then((response) => {
        if (!isMountedRef.current) {
          return;
        }

        if (!isNonEmptyArray(response.response.jetPassTimeSlots)) {
          // Finns inte att välja på. Skriv det.
          return;
        }

        const rideIds = response.response.jetPassTimeSlots.map((jetPassTimeSlot) => jetPassTimeSlot.attractionId);
        let modifiedRides = false;
        for (const rideId of rideIds) {
          if (!rides.has(rideId)) {
            const ride = RideStore.getRideById(rideId);
            if (ride) {
              rides.set(rideId, ride);
              modifiedRides = true;
            }
          }
        }

        if (modifiedRides) {
          setRides(new Map<number, RideBlock>(rides));
        }

        setRidesForSelectedDate(response.response.jetPassTimeSlots);
      })
      .catch((err) => {
        console.error(err);
      });
  }, [selectedDate]);

  return (
    <div className={styles.wrapper}>
      <ul className={styles.rideList}>
        {isNonEmptyArray(ridesForSelectedDate)
          ? ridesForSelectedDate.map((ride) => {
              const rideBlock = rides.get(ride.attractionId);
              const isSelected =
                firstGuest?.admissionProduct?.selectedMandatoryJetpass?.attractionId === ride.attractionId || false;
              const timeSlot = isNonEmptyArray(ride.timeSlots) ? ride.timeSlots[0] : undefined;
              const hasSlotsLeftForGuests = timeSlot ? timeSlot.quantity >= guests.length : false;
              const buttonLabelIfHasSlotsLeft = isSelected
                ? t("selectMandatoryJetpassStepChoice")
                : t("selectMandatoryJetpassStepChoose");
              const buttonLabelIfNoSlotsLeft = timeSlot
                ? t("selectMandatoryJetpassStepSpotsLeft", { count: timeSlot.quantity })
                : t("soldOut");

              return (
                <li key={ride.attractionId} className={styles.rideListItem}>
                  <MandatoryJetpassCard
                    entrance={ride}
                    timeSlot={timeSlot}
                    title={rideBlock ? rideBlock.title : ""}
                    preamble={rideBlock ? rideBlock.preamble : null}
                    shortDescriptionInList={rideBlock ? rideBlock.shortDescriptionInList : ""}
                    imageUrl={rideBlock?.imageInList?.file.url}
                    buttonLabel={hasSlotsLeftForGuests ? buttonLabelIfHasSlotsLeft : buttonLabelIfNoSlotsLeft}
                    isSelected={isSelected}
                    isSoldOut={!hasSlotsLeftForGuests}
                    onClickButton={onClickMandatoryJetpass}
                  />
                </li>
              );
            })
          : null}
      </ul>
      <ButtonRow
        stepIndex={stepIndex}
        onClickBack={onClickBack}
        onClickStepComplete={onClickStepComplete}
        nextDisabled={!hasSelectedMandatoryJetpass}
      />
    </div>
  );
};

export default SelectMandatoryJetpass;
